        public async IAsyncEnumerable<GeminiStreamChunk> QueryStreamAsync(
            string question,
            IReadOnlyList<(string Role, string Text)> history,
            (string MimeType, string Base64Data)? image,
            string? accountTypeCode)
        {
            var client = CreateClient();
            var identity = DetermineIdentity(history, question, accountTypeCode);

            object[] userTurnParts = image is { } img
                ? new object[]
                {
                    new { inlineData = new { mimeType = img.MimeType, data = img.Base64Data } },
                    new { text = question },
                }
                : new object[] { new { text = question } };

            var contents = history
                .Select(h => new { role = h.Role, parts = new object[] { new { text = h.Text } } })
                .Append(new { role = "user", parts = userTurnParts })
                .ToArray();

            var requestBody = new
            {
                contents,
                systemInstruction = new { parts = new[] { new { text = BuildSystemInstruction(identity) } } },
                generationConfig = new { temperature = 0.7 },
            };

            using var content = new StringContent(JsonSerializer.Serialize(requestBody), Encoding.UTF8, "application/json");
            using var request = new HttpRequestMessage(
                HttpMethod.Post,
                $"/v1beta/models/{_appSetting.GeminiModel}:streamGenerateContent?alt=sse")
            {
                Content = content,
            };

            using var resp = await client.SendAsync(request, HttpCompletionOption.ResponseHeadersRead);

            if (!resp.IsSuccessStatusCode)
            {
                var errorBody = await resp.Content.ReadAsStringAsync();
                _logger.LogError("Gemini streamGenerateContent (flow 8) failed: {Status} {Body}", resp.StatusCode, errorBody);
                yield return new GeminiStreamChunk { Error = $"Gemini API 呼叫失敗 ({(int)resp.StatusCode}): {errorBody}" };
                yield break;
            }

            await using var stream = await resp.Content.ReadAsStreamAsync();
            using var reader = new StreamReader(stream, Encoding.UTF8);

            string? line;
            while ((line = await reader.ReadLineAsync()) != null)
            {
                if (!line.StartsWith("data: "))
                    continue;

                using var doc = JsonDocument.Parse(line["data: ".Length..]);

                if (!doc.RootElement.TryGetProperty("candidates", out var candidates) || candidates.GetArrayLength() == 0)
                    continue;

                var candidate = candidates[0];

                if (candidate.TryGetProperty("content", out var contentEl) &&
                    contentEl.TryGetProperty("parts", out var parts))
                {
                    foreach (var part in parts.EnumerateArray())
                    {
                        if (part.TryGetProperty("text", out var textEl))
                        {
                            var text = textEl.GetString();
                            if (!string.IsNullOrEmpty(text))
                                yield return new GeminiStreamChunk { Delta = text };
                        }
                    }
                }
            }

            yield return new GeminiStreamChunk { Done = true, Source = "" };
        }
    }
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import type { ReactNode } from 'react'
import type { Answer, Exploration, SelfAwarenessCard, SummarySection } from '@/types'
import { getExploration, updateExploration } from '@/storage/explorations'
import { useAutosave } from '@/hooks/useAutosave'

interface ExplorationContextValue {
  exploration: Exploration | null
  setAnswer: (questionIndex: number, text: string) => void
  truncateAfter: (questionIndex: number) => void
  finish: (summary: SummarySection[], card: SelfAwarenessCard) => void
}

const ExplorationContext = createContext<ExplorationContextValue | null>(null)

export function ExplorationProvider({ id, children }: { id: string; children: ReactNode }) {
  const [exploration, setExploration] = useState<Exploration | null>(() => getExploration(id))

  const { flush } = useAutosave(exploration, (e) => {
    if (!e) return
    try {
      updateExploration(e.id, {
        answers: e.answers,
        summary: e.summary,
        card: e.card,
        status: e.status
      })
    } catch {
      // exploration removed from storage while in memory — fail silently for demo
    }
  }, 300)

  // flush 先於 state reset
  useEffect(() => {
    return () => { flush() }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id])

  useEffect(() => { setExploration(getExploration(id)) }, [id])

  const setAnswer = useCallback((questionIndex: number, text: string) => {
    setExploration(prev => {
      if (!prev) return prev
      const now = new Date().toISOString()
      const answers: Answer[] = [...prev.answers]
      const idx = answers.findIndex(a => a.questionIndex === questionIndex)
      if (idx >= 0) answers[idx] = { ...answers[idx], text, updatedAt: now }
      else answers.push({ questionIndex, text, updatedAt: now })
      return { ...prev, answers, updatedAt: now }
    })
  }, [])

  const truncateAfter = useCallback((questionIndex: number) => {
    setExploration(prev => {
      if (!prev) return prev
      return {
        ...prev,
        answers: questionIndex < 0 ? [] : prev.answers.filter(a => a.questionIndex <= questionIndex),
        summary: undefined,
        card: undefined,
        status: 'in-progress' as const,
        updatedAt: new Date().toISOString()
      }
    })
  }, [])

  const finish = useCallback((summary: SummarySection[], card: SelfAwarenessCard) => {
    setExploration(prev => {
      if (!prev) return prev
      return { ...prev, summary, card, status: 'completed' as const, updatedAt: new Date().toISOString() }
    })
  }, [])

  const value = useMemo(
    () => ({ exploration, setAnswer, truncateAfter, finish }),
    [exploration, setAnswer, truncateAfter, finish]
  )

  return <ExplorationContext.Provider value={value}>{children}</ExplorationContext.Provider>
}

export function useExploration(): ExplorationContextValue {
  const ctx = useContext(ExplorationContext)
  if (!ctx) throw new Error('useExploration must be used within ExplorationProvider')
  return ctx
}

