import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import type { ReactNode } from 'react'

/** 光的色溫階段：冷（過去·契機）→ 中（現在·內在狀態）→ 暖（未來·前行） */
export type StageTone = 'cool' | 'mid' | 'warm'

/** 實景背景照片；null 表示只以漸層光斑呈現 */
export type StageBackdrop = 'dawn' | 'day' | 'sunset' | 'night'

export interface StageScene {
  tone: StageTone
  backdrop: StageBackdrop | null
  /** 實景照片主導的場景會關閉漸層光斑，避免兩層顏色互相打架 */
  dimGlow: boolean
}

export const DEFAULT_STAGE_SCENE: StageScene = { tone: 'cool', backdrop: null, dimGlow: false }

interface StageContextValue {
  scene: StageScene
  setScene: (scene: StageScene) => void
}

const StageContext = createContext<StageContextValue | null>(null)

export function StageSceneProvider({ children }: { children: ReactNode }) {
  const [scene, setSceneState] = useState<StageScene>(DEFAULT_STAGE_SCENE)

  const setScene = useCallback((next: StageScene) => {
    setSceneState(prev =>
      prev.tone === next.tone && prev.backdrop === next.backdrop && prev.dimGlow === next.dimGlow
        ? prev
        : next
    )
  }, [])

  const value = useMemo(() => ({ scene, setScene }), [scene, setScene])
  return <StageContext.Provider value={value}>{children}</StageContext.Provider>
}

export function useStage(): StageContextValue {
  const ctx = useContext(StageContext)
  if (!ctx) throw new Error('useStage must be used within StageSceneProvider')
  return ctx
}

/**
 * 由場景頁面宣告自己需要的舞台狀態。
 * 以基本型別作為相依，避免每次 render 產生新物件而重複觸發。
 */
export function useStageScene(
  tone: StageTone,
  backdrop: StageBackdrop | null = null,
  dimGlow = false
): void {
  const { setScene } = useStage()
  useEffect(() => {
    setScene({ tone, backdrop, dimGlow })
  }, [setScene, tone, backdrop, dimGlow])
}

import { useCallback, useEffect, useState } from 'react'
import { useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { SpotlightText } from '@/components/animations/SpotlightText'
import { Scene } from '@/components/ui/Scene'
import { Button } from '@/components/ui/Button'
import { Dialog } from '@/components/ui/Dialog'
import { ProgressLight } from '@/components/ui/ProgressLight'
import { useToast } from '@/components/ui/Toast'
import { useStage } from '@/components/stage/StageContext'
import type { StageBackdrop, StageTone } from '@/components/stage/StageContext'
import { ExplorationProvider, useExploration } from '@/contexts/ExplorationContext'
import { useSettings } from '@/contexts/SettingsContext'
import { useTypewriter } from '@/hooks/useTypewriter'
import { DEMO_QUESTIONS } from '@/data/demo-dialogue'
import styles from './ExplorationPage.module.css'

const TOTAL = DEMO_QUESTIONS.length

type Phase = 'reflection' | 'question'

function toneForIndex(index: number): StageTone {
  if (index < 3) return 'cool'
  if (index < 7) return 'mid'
  return 'warm'
}

function backdropForIndex(index: number): StageBackdrop {
  if (index < 2) return 'dawn'
  if (index < 5) return 'day'
  if (index < 8) return 'sunset'
  return 'night'
}

function ExplorationInner() {
  const { t } = useTranslation()
  const { reduceMotion, settings } = useSettings()
  const { exploration, setAnswer, truncateAfter } = useExploration()
  const { showToast } = useToast()
  const { setScene } = useStage()
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()

  const requestedQuestion = Number(searchParams.get('q'))
  const [currentIndex, setCurrentIndex] = useState(() =>
    Number.isFinite(requestedQuestion) && requestedQuestion >= 1
      ? Math.min(TOTAL, Math.trunc(requestedQuestion)) - 1
      : 0
  )
  const [phase, setPhase] = useState<Phase>(
    Number.isFinite(requestedQuestion) && requestedQuestion >= 1 ? 'question' : 'reflection'
  )
  const [draft, setDraft] = useState('')
  const [hintOpen, setHintOpen] = useState(false)
  const [reviseDialogOpen, setReviseDialogOpen] = useState(false)
  const [reviseTarget, setReviseTarget] = useState<number | null>(null)

  const question = DEMO_QUESTIONS[currentIndex]
  const activeText = phase === 'reflection' ? question.empathy : question.question
  const { displayed, done } = useTypewriter({
    text: activeText,
    enabled: !reduceMotion,
    tickMs: settings.typingSpeedMs
  })

  // 探索場景由實景照片主導，關閉漸層光斑
  useEffect(() => {
    setScene({
      tone: toneForIndex(currentIndex),
      backdrop: backdropForIndex(currentIndex),
      dimGlow: true
    })
  }, [setScene, currentIndex])

  // 換題時載入該題已保存的回答
  useEffect(() => {
    setDraft(exploration?.answers.find(a => a.questionIndex === currentIndex)?.text ?? '')
    setHintOpen(false)
    // 僅在題號改變時同步草稿，避免覆寫使用者正在輸入的內容
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentIndex])

  const updateDraft = useCallback(
    (value: string) => {
      setDraft(value)
      setAnswer(currentIndex, value)
    },
    [currentIndex, setAnswer]
  )

  const advance = useCallback(() => {
    if (currentIndex < TOTAL - 1) {
      setCurrentIndex(index => index + 1)
      setPhase('reflection')
      return
    }
    if (exploration) navigate(`/settle/${exploration.id}`)
  }, [currentIndex, exploration, navigate])

  const requestRevise = useCallback((target: number) => {
    setReviseTarget(target)
    setReviseDialogOpen(true)
  }, [])

  const goBack = useCallback(() => {
    if (currentIndex === 0) {
      navigate('/topic')
      return
    }
    requestRevise(currentIndex - 1)
  }, [currentIndex, navigate, requestRevise])

  const closeReviseDialog = useCallback(() => {
    setReviseDialogOpen(false)
    setReviseTarget(null)
  }, [])

  const confirmRevise = useCallback(() => {
    const target = reviseTarget ?? currentIndex - 1
    truncateAfter(target)
    setCurrentIndex(target)
    setPhase('question')
    setReviseDialogOpen(false)
    setReviseTarget(null)
  }, [reviseTarget, currentIndex, truncateAfter])

  if (!exploration) return <Scene>{t('history.notFound')}</Scene>

  const progressNodes = DEMO_QUESTIONS.map((q, i) => ({
    question: q.question,
    answer: exploration.answers.find(a => a.questionIndex === i)?.text,
    answered: exploration.answers.some(a => a.questionIndex === i)
  }))

  const narrative = {
    cool: t('exploration.stageCool'),
    mid: t('exploration.stageMid'),
    warm: t('exploration.stageWarm')
  }[toneForIndex(currentIndex)]

  const revealed = reduceMotion ? activeText.length : displayed.length
  const typingDone = reduceMotion || done

  return (
    <>
      <div className={styles.narrative}>{narrative}</div>

      {phase === 'reflection' ? (
        <div
          className={styles.reflection}
          onClick={() => setPhase('question')}
        >
          <div className={styles.reflectionInner}>
            <p className={styles.reflectionText}>
              <SpotlightText text={question.empathy} revealed={revealed} />
            </p>
            <div className={styles.continueSlot}>
              <div className={styles.continueHint}>{t('exploration.continueHint')}</div>
            </div>
          </div>
        </div>
      ) : (
        <div className={styles.questionScene}>
          <div className={styles.questionInner}>
            <div className={styles.counter}>{String(currentIndex + 1).padStart(2, '0')}</div>
            <p className={styles.questionText}>
              <SpotlightText text={question.question} revealed={revealed} />
            </p>

            {typingDone && (
              <div className={styles.answerBlock}>
                <div className={styles.answerWrap}>
                  <textarea
                    className={styles.answer}
                    value={draft}
                    placeholder={t('exploration.inputPlaceholder')}
                    aria-label={t('exploration.inputLabel')}
                    onChange={event => updateDraft(event.target.value)}
                  />
                  <div
                    className={styles.hintChip}
                    onMouseEnter={() => setHintOpen(true)}
                    onMouseLeave={() => setHintOpen(false)}
                  >
                    <span className={styles.hintMark} aria-hidden>
                      ?
                    </span>
                    <span className={styles.hintLabel}>{t('exploration.hintTrigger')}</span>
                    {hintOpen && (
                      <div className={styles.hintBubble} role="tooltip">
                        <div className={styles.hintBubbleTitle}>{t('exploration.hintTitle')}</div>
                        {t('exploration.hint')}
                        <div className={styles.hintArrow} aria-hidden />
                      </div>
                    )}
                  </div>
                </div>

                <div className={styles.actions}>
                  <div className={styles.actionsLeft}>
                    <button
                      type="button"
                      className={styles.mic}
                      title={t('exploration.mic')}
                      aria-label={t('exploration.mic')}
                      onClick={() => showToast(t('exploration.micNote'))}
                    >
                      <svg width="18" height="20" viewBox="0 0 18 20" aria-hidden>
                        <rect
                          x="6"
                          y="1.5"
                          width="6"
                          height="11"
                          rx="3"
                          fill="none"
                          stroke="rgba(255,255,255,.55)"
                          strokeWidth="1.3"
                        />
                        <line x1="9" y1="15.5" x2="9" y2="18" stroke="rgba(255,255,255,.55)" strokeWidth="1.3" />
                        <line x1="5" y1="18" x2="13" y2="18" stroke="rgba(255,255,255,.55)" strokeWidth="1.3" />
                      </svg>
                    </button>
                    <Button
                      variant="text"
                      className={styles.sample}
                      onClick={() => updateDraft(question.sampleAnswer)}
                    >
                      {t('exploration.fillSample')}
                    </Button>
                  </div>

                  <div className={styles.actionsRight}>
                    <Button variant="text" onClick={goBack}>
                      {currentIndex === 0 ? t('exploration.backToTopic') : t('exploration.prev')}
                    </Button>
                    <Button className={styles.submit} onClick={advance}>
                      {currentIndex === TOTAL - 1 ? t('exploration.finish') : t('exploration.next')}
                    </Button>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      <ProgressLight
        title={t('exploration.progressTitle')}
        caption={t('exploration.progressCaption', { current: currentIndex + 1, total: TOTAL })}
        nodes={progressNodes}
        currentIndex={currentIndex}
        onJump={requestRevise}
      />

      <Dialog
        open={reviseDialogOpen}
        title={t('exploration.reviseDialogTitle')}
        onClose={closeReviseDialog}
        actions={
          <>
            <Button variant="secondary" compact onClick={closeReviseDialog}>
              {t('exploration.reviseCancel')}
            </Button>
            <Button variant="danger" onClick={confirmRevise}>
              {t('exploration.reviseConfirm')}
            </Button>
          </>
        }
      >
        {t('exploration.reviseDialogBody')}
      </Dialog>
    </>
  )
}

export function ExplorationPage() {
  const { id } = useParams<{ id: string }>()
  const [searchParams] = useSearchParams()
  if (!id) return null
  // 以 id + ?q 作為 key：切換到不同探索（或指定題號）時整棵子樹重新掛載，
  // 讓 ExplorationInner 依 ?q 重新初始化題號；否則同屬 /explore/:id 路由的
  // 前後導覽會重用元件、忽略新的 ?q（例如從探索中途「直接跳到第 10 題」失效）。
  return (
    <ExplorationProvider key={`${id}:${searchParams.get('q') ?? ''}`} id={id}>
      <ExplorationInner />
    </ExplorationProvider>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'

interface Options {
  text: string
  charsPerTick?: number
  tickMs?: number
  enabled?: boolean
}

/**
 * 逐字揭示。整段文字由呼叫端一開始就渲染，本 hook 只回報「已揭示的字數」。
 *
 * 揭示的計時器由「單一」effect 擁有並在完成時自我清除；不再拆成
 * reset / start / clear-on-complete 三個共用同一個 ref 的 effect，
 * 以避免 React StrictMode（開發模式）雙重掛載時三個 effect 互相競速、
 * 提前清掉計時器而讓揭示卡在中途。
 */
export function useTypewriter({
  text,
  charsPerTick = 1,
  tickMs = 30,
  enabled = true
}: Options): { displayed: string; done: boolean; skip: () => void } {
  const [count, setCount] = useState(enabled ? 0 : text.length)
  const intervalRef = useRef<number | null>(null)

  useEffect(() => {
    // 清掉前一輪可能還在跑的計時器（text / 速度 / enabled 改變時重新開始）
    if (intervalRef.current !== null) {
      window.clearInterval(intervalRef.current)
      intervalRef.current = null
    }

    // 動態關閉：直接顯示全文，不啟動計時器
    if (!enabled) {
      setCount(text.length)
      return
    }

    // 從頭開始揭示
    setCount(0)
    if (text.length === 0) return

    const id = window.setInterval(() => {
      setCount(c => {
        const next = Math.min(text.length, c + charsPerTick)
        // 完成時，計時器在自己的 callback 內自我清除，避免跨 effect 競速
        if (next >= text.length && intervalRef.current !== null) {
          window.clearInterval(intervalRef.current)
          intervalRef.current = null
        }
        return next
      })
    }, tickMs)
    intervalRef.current = id

    return () => {
      window.clearInterval(id)
      if (intervalRef.current === id) intervalRef.current = null
    }
  }, [text, enabled, charsPerTick, tickMs])

  const skip = useCallback(() => {
    if (intervalRef.current !== null) {
      window.clearInterval(intervalRef.current)
      intervalRef.current = null
    }
    setCount(text.length)
  }, [text.length])

  return {
    displayed: text.slice(0, count),
    done: count >= text.length,
    skip
  }
}

import { useEffect, useRef } from 'react'
import styles from './ImmersiveStage.module.css'

interface StarPixel {
  x: number
  y: number
  color: string
  max: number
  size: number
  base: number
  speed: number
  reverse: boolean
}

const GRID_GAP = 20
const FILL_RATIO = 0.28
const STAR_COLORS = ['#ffffff', '#e6c9a0', '#cfe0f5', '#fff3d6']

/**
 * 星空 · 像素微光。以 canvas 逐格繪製忽明忽暗的方形微光點
 * （設計稿參數：gap 20 / 取樣率 0.28 / 4 色交替）。
 */
export function StarfieldCanvas({ reduceMotion }: { reduceMotion: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return

    // 測試環境（jsdom）沒有 canvas 實作，取不到 context 就靜靜跳過
    let context: CanvasRenderingContext2D | null = null
    try {
      context = canvas.getContext('2d')
    } catch {
      return
    }
    if (!context) return
    const ctx = context

    let pixels: StarPixel[] = []
    let width = 0
    let height = 0
    let frame = 0

    const build = () => {
      const host = canvas.parentElement
      width = host?.clientWidth ?? window.innerWidth
      height = host?.clientHeight ?? window.innerHeight
      if (!width || !height) return
      const ratio = Math.min(window.devicePixelRatio || 1, 2)
      canvas.width = width * ratio
      canvas.height = height * ratio
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0)

      const next: StarPixel[] = []
      let index = 0
      for (let x = 0; x < width; x += GRID_GAP) {
        for (let y = 0; y < height; y += GRID_GAP) {
          index += 1
          if (Math.random() > FILL_RATIO) continue
          const max = 0.6 + Math.random() * 1.3
          next.push({
            x: x + Math.random() * GRID_GAP,
            y: y + Math.random() * GRID_GAP,
            color: STAR_COLORS[index % STAR_COLORS.length],
            max,
            size: Math.random() * max,
            base: 0.4 + Math.random() * 0.55,
            speed: (0.1 + Math.random() * 0.9) * 0.012,
            reverse: Math.random() > 0.5
          })
        }
      }
      pixels = next
    }

    const drawStatic = () => {
      ctx.clearRect(0, 0, width, height)
      for (const pixel of pixels) {
        ctx.globalAlpha = pixel.base
        ctx.fillStyle = pixel.color
        ctx.fillRect(pixel.x, pixel.y, pixel.max, pixel.max)
      }
      ctx.globalAlpha = 1
    }

    const step = () => {
      frame = requestAnimationFrame(step)
      ctx.clearRect(0, 0, width, height)
      for (const pixel of pixels) {
        if (pixel.size >= pixel.max) pixel.reverse = true
        else if (pixel.size <= 0) pixel.reverse = false
        pixel.size += pixel.reverse ? -pixel.speed : pixel.speed
        const size = pixel.size > 0 ? pixel.size : 0
        ctx.globalAlpha = Math.min(1, (size / pixel.max) * pixel.base + 0.12)
        ctx.fillStyle = pixel.color
        const offset = (pixel.max - size) / 2
        ctx.fillRect(pixel.x + offset, pixel.y + offset, size, size)
      }
      ctx.globalAlpha = 1
    }

    const start = () => {
      build()
      cancelAnimationFrame(frame)
      if (reduceMotion) drawStatic()
      else frame = requestAnimationFrame(step)
    }

    start()

    const observer =
      typeof ResizeObserver === 'function' ? new ResizeObserver(() => start()) : null
    if (observer && canvas.parentElement) observer.observe(canvas.parentElement)
    window.addEventListener('resize', start)

    return () => {
      cancelAnimationFrame(frame)
      observer?.disconnect()
      window.removeEventListener('resize', start)
    }
  }, [reduceMotion])

  return <canvas ref={canvasRef} className={styles.starfield} aria-hidden />
}

import { useEffect, useRef } from 'react'
import styles from './ImmersiveStage.module.css'

const SPARK_RADIUS = 15
const RAY_ANGLES = [0, 90, 180, 270]
const DOT_COUNT = 8

/**
 * 點擊光效：細線十字 + 環形微粒，作為「光回應觸碰」的一致回饋。
 * 使用 Web Animations API，動畫結束即移除節點，不留 DOM 殘留。
 */
export function ClickSparkLayer({ reduceMotion }: { reduceMotion: boolean }) {
  const layerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const layer = layerRef.current
    if (!layer) return

    const spawn = (clientX: number, clientY: number) => {
      const rect = layer.getBoundingClientRect()
      const x = clientX - rect.left
      const y = clientY - rect.top
      if (x < 0 || y < 0 || x > rect.width || y > rect.height) return

      const accent =
        getComputedStyle(layer).getPropertyValue('--color-accent').trim() || '#e6c9a0'

      const animate = (
        node: HTMLElement,
        frames: Keyframe[],
        options: KeyframeAnimationOptions
      ) => {
        layer.appendChild(node)
        if (typeof node.animate !== 'function') {
          node.remove()
          return
        }
        const animation = node.animate(frames, options)
        animation.onfinish = () => node.remove()
        animation.oncancel = () => node.remove()
      }

      const flash = document.createElement('div')
      flash.className = styles.sparkFlash
      flash.style.left = `${x}px`
      flash.style.top = `${y}px`
      flash.style.borderColor = accent
      animate(
        flash,
        [
          { transform: 'scale(.4)', opacity: 0.8 },
          { transform: 'scale(2.4)', opacity: 0 }
        ],
        { duration: reduceMotion ? 280 : 520, easing: 'cubic-bezier(.2,.7,.3,1)' }
      )

      if (reduceMotion) return

      for (const degree of RAY_ANGLES) {
        const ray = document.createElement('div')
        ray.className = styles.sparkRay
        ray.style.left = `${x}px`
        ray.style.top = `${y}px`
        ray.style.background = accent
        animate(
          ray,
          [
            { transform: `rotate(${degree}deg) translateX(3px)`, opacity: 0.85 },
            { transform: `rotate(${degree}deg) translateX(${SPARK_RADIUS}px)`, opacity: 0 }
          ],
          { duration: 500, easing: 'cubic-bezier(.2,.7,.3,1)' }
        )
      }

      for (let i = 0; i < DOT_COUNT; i += 1) {
        const dot = document.createElement('div')
        dot.className = styles.sparkDot
        dot.style.left = `${x}px`
        dot.style.top = `${y}px`
        dot.style.background = accent
        dot.style.boxShadow = `0 0 5px ${accent}`
        const angle = (i * 45 * Math.PI) / 180 + Math.PI / 8
        animate(
          dot,
          [
            { transform: 'translate(0,0) scale(1)', opacity: 0.9 },
            {
              transform: `translate(${(Math.cos(angle) * SPARK_RADIUS).toFixed(1)}px,${(
                Math.sin(angle) * SPARK_RADIUS
              ).toFixed(1)}px) scale(0)`,
              opacity: 0
            }
          ],
          { duration: 560, easing: 'cubic-bezier(.15,.7,.25,1)' }
        )
      }
    }

    const onClick = (event: MouseEvent) => spawn(event.clientX, event.clientY)
    window.addEventListener('click', onClick)
    return () => window.removeEventListener('click', onClick)
  }, [reduceMotion])

  return <div ref={layerRef} className={styles.sparkLayer} aria-hidden />
}

import { useMemo } from 'react'
import styles from './SpotlightText.module.css'

const NON_BREAKING_SPACE = '\u00a0'

interface SpotlightTextProps {
  text: string
  /** 已點亮的字數 */
  revealed: number
  className?: string
}

/**
 * 聚光揭字：整段文字一開始就在版面上（避免行距跳動），
 * 未讀到的字以極低透明度存在，讀到的字逐一亮起。
 */
export function SpotlightText({ text, revealed, className }: SpotlightTextProps) {
  const chars = useMemo(() => Array.from(text), [text])

  return (
    <span className={className} aria-label={text}>
      {chars.map((char, index) => (
        <span
          // 同一段文字中字元可能重複，索引是穩定且唯一的鍵
          key={`${index}-${char}`}
          aria-hidden
          className={`${styles.char} ${index < revealed ? styles.lit : styles.dim}`}
        >
          {char === ' ' ? NON_BREAKING_SPACE : char}
        </span>
      ))}
    </span>
  )
}

