import { useEffect, useRef } from 'react'
import type { CSSProperties, ReactNode } from 'react'
import { useSettings } from '@/contexts/SettingsContext'
import { StarfieldCanvas } from './StarfieldCanvas'
import { ClickSparkLayer } from './ClickSparkLayer'
import { SceneMenu } from './SceneMenu'
import { MotionToggle } from './MotionToggle'
import { DEFAULT_STAGE_SCENE, StageSceneProvider, useStage } from './StageContext'
import type { StageBackdrop, StageTone } from './StageContext'
import styles from './ImmersiveStage.module.css'

interface ToneSpec {
  glowA: string
  glowB: string
  anchorAX: string
  anchorAY: string
  anchorBX: string
  anchorBY: string
  opacity: number
  opacityReduced: number
}

/** 三段色溫，對應設計稿 applyVars() 的 cool / mid / warm 取值 */
const TONE_SPECS: Record<StageTone, ToneSpec> = {
  cool: {
    glowA: '#1f4d73',
    glowB: '#155e63',
    anchorAX: '22%',
    anchorAY: '20%',
    anchorBX: '82%',
    anchorBY: '78%',
    opacity: 0.46,
    opacityReduced: 0.26
  },
  mid: {
    glowA: '#4a4166',
    glowB: '#7d5f3c',
    anchorAX: '30%',
    anchorAY: '42%',
    anchorBX: '74%',
    anchorBY: '70%',
    opacity: 0.52,
    opacityReduced: 0.28
  },
  warm: {
    glowA: '#a2632b',
    glowB: '#c8913f',
    anchorAX: '48%',
    anchorAY: '92%',
    anchorBX: '72%',
    anchorBY: '74%',
    opacity: 0.6,
    opacityReduced: 0.32
  }
}

/** 背景照片位於 public/assets，以 BASE_URL 組出絕對路徑，避免巢狀路由下相對路徑失效 */
const ASSET_BASE = import.meta.env.BASE_URL

const BACKDROPS: { key: StageBackdrop; src: string }[] = [
  { key: 'night', src: `${ASSET_BASE}assets/bg-night.jpg` },
  { key: 'day', src: `${ASSET_BASE}assets/bg-day.jpg` },
  { key: 'sunset', src: `${ASSET_BASE}assets/bg-sunset.jpg` },
  { key: 'dawn', src: `${ASSET_BASE}assets/bg-dawn.jpg` }
]

const BLOOM_KEYFRAMES: Keyframe[] = [
  { transform: 'scale(1)' },
  { transform: 'scale(1.06)', offset: 0.5 },
  { transform: 'scale(1)' }
]

function StageSurface({ children }: { children: ReactNode }) {
  const { reduceMotion } = useSettings()
  const { scene } = useStage()
  const backdropRef = useRef<HTMLDivElement>(null)
  const previousBackdrop = useRef<StageBackdrop | null>(null)

  const tone = TONE_SPECS[scene.tone] ?? TONE_SPECS[DEFAULT_STAGE_SCENE.tone]
  const glowOpacity = scene.dimGlow ? 0 : reduceMotion ? tone.opacityReduced : tone.opacity

  // 背景照片換場時，讓整層極緩慢地呼吸一次，避免硬切
  useEffect(() => {
    const layer = backdropRef.current
    const changed = previousBackdrop.current !== scene.backdrop
    previousBackdrop.current = scene.backdrop
    if (!layer || !changed || reduceMotion || !scene.backdrop) return
    if (typeof layer.animate !== 'function') return
    layer.animate(BLOOM_KEYFRAMES, { duration: 7000, easing: 'cubic-bezier(.45,0,.55,1)' })
  }, [scene.backdrop, reduceMotion])

  const stageStyle: CSSProperties = {
    ['--stage-glow-a' as string]: tone.glowA,
    ['--stage-glow-b' as string]: tone.glowB,
    ['--stage-glow-a-x' as string]: tone.anchorAX,
    ['--stage-glow-a-y' as string]: tone.anchorAY,
    ['--stage-glow-b-x' as string]: tone.anchorBX,
    ['--stage-glow-b-y' as string]: tone.anchorBY,
    ['--stage-glow-opacity' as string]: String(glowOpacity)
  }

  return (
    <div className={styles.root} style={stageStyle}>
      <div className={`${styles.glowAnchor} ${styles.glowAnchorA}`} aria-hidden>
        <div className={`${styles.glowOrb} ${styles.glowA}`} />
      </div>
      <div className={`${styles.glowAnchor} ${styles.glowAnchorB}`} aria-hidden>
        <div className={`${styles.glowOrb} ${styles.glowB}`} />
      </div>
      <div className={`${styles.glowAnchor} ${styles.glowAnchorC}`} aria-hidden>
        <div className={`${styles.glowOrb} ${styles.glowC}`} />
      </div>

      {scene.backdrop && (
        <div ref={backdropRef} className={styles.backdrop} aria-hidden>
          {BACKDROPS.map(item => (
            <div
              key={item.key}
              className={`${styles.backdropLayer} ${
                item.key === scene.backdrop ? styles.backdropLayerActive : ''
              }`}
              style={{ backgroundImage: `url(${item.src})` }}
            />
          ))}
        </div>
      )}

      <StarfieldCanvas reduceMotion={reduceMotion} />
      <ClickSparkLayer reduceMotion={reduceMotion} />
      <div className={styles.topRightCluster}>
        <MotionToggle />
        <SceneMenu />
      </div>

      {children}
    </div>
  )
}

/** 常駐於所有場景之下的沉浸舞台：漸層光斑、實景背景、星空、點擊光效。 */
export function ImmersiveStage({ children }: { children: ReactNode }) {
  return (
    <StageSceneProvider>
      <StageSurface>{children}</StageSurface>
    </StageSceneProvider>
  )
}

import { toPng } from 'html-to-image'

export async function exportNodeAsPng(node: HTMLElement, filename: string): Promise<void> {
  // 先等 webfont 載入完成，避免截圖時字型回退造成成品不一致
  if (typeof document !== 'undefined' && document.fonts?.ready) {
    await document.fonts.ready
  }
  const dataUrl = await toPng(node, { pixelRatio: 2, cacheBust: true })
  const link = document.createElement('a')
  link.download = filename
  link.href = dataUrl
  document.body.appendChild(link)
  link.click()
  link.remove()
}

import * as XLSX from 'xlsx'
import type { Exploration } from '@/types'

export function buildExplorationWorkbook(exploration: Exploration): XLSX.WorkBook {
  const wb = XLSX.utils.book_new()

  // 總覽 sheet
  const overview = [
    ['議題類型', exploration.topicCustomLabel ?? exploration.topic],
    ['建立時間', exploration.createdAt],
    ['完成狀態', exploration.status],
    ['最後更新', exploration.updatedAt]
  ]
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(overview), '總覽')

  // 10 題問答 sheet
  const qaRows: (string | number)[][] = [['題號', '回答', '更新時間']]
  for (const a of exploration.answers) {
    qaRows.push([a.questionIndex + 1, a.text, a.updatedAt])
  }
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(qaRows), '10 題問答')

  // 總結 sheet
  const summaryRows: string[][] = [['段落', '標題', '內容']]
  for (const s of exploration.summary ?? []) {
    // key is an internal identifier; title carries the human-readable label
    summaryRows.push([s.key, s.title, s.body])
  }
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(summaryRows), '總結')

  // 推薦資源 sheet
  const resourceRows: string[][] = [['名稱', '類型', '連結', '推薦原因']]
  for (const r of exploration.card?.resources ?? []) {
    resourceRows.push([r.name, r.type, r.url, r.reason])
  }
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(resourceRows), '推薦資源')

  return wb
}

export function exportExplorationAsXlsx(exploration: Exploration, filename: string): void {
  const wb = buildExplorationWorkbook(exploration)
  XLSX.writeFile(wb, filename)
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import type { ReactNode } from 'react'
import { useTranslation } from 'react-i18next'
import type { Settings } from '@/types'
import { readSettings, writeSettings } from '@/storage/settings'
import { useReducedMotion } from '@/hooks/useReducedMotion'

interface SettingsContextValue {
  settings: Settings
  updateSettings: (patch: Partial<Settings>) => void
  reduceMotion: boolean
}

const SettingsContext = createContext<SettingsContextValue | null>(null)

export function SettingsProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<Settings>(() => {
    const base = readSettings()
    if (import.meta.env.MODE === 'test') return { ...base, motionMode: 'reduced' }
    return base
  })
  const { i18n } = useTranslation()

  useEffect(() => {
    if (i18n.language !== settings.locale) {
      i18n.changeLanguage(settings.locale)
    }
    document.documentElement.setAttribute(
      'lang',
      settings.locale === 'en' ? 'en' : 'zh-Hant-TW'
    )
  }, [settings.locale, i18n])

  const updateSettings = useCallback((patch: Partial<Settings>) => {
    writeSettings(patch)
    setSettings(prev => ({ ...prev, ...patch }))
  }, [])

  const reduceMotion = useReducedMotion(settings.motionMode)

  const value = useMemo(
    () => ({ settings, updateSettings, reduceMotion }),
    [settings, updateSettings, reduceMotion]
  )

  return <SettingsContext.Provider value={value}>{children}</SettingsContext.Provider>
}

export function useSettings(): SettingsContextValue {
  const ctx = useContext(SettingsContext)
  if (!ctx) throw new Error('useSettings must be used within SettingsProvider')
  return ctx
}

