import type { ReactNode } from 'react'
import styles from './Checkbox.module.css'

interface CheckboxProps {
  checked: boolean
  onChange: (checked: boolean) => void
  children: ReactNode
}

export function Checkbox({ checked, onChange, children }: CheckboxProps) {
  return (
    <label className={styles.label}>
      <input
        type="checkbox"
        className={styles.native}
        checked={checked}
        onChange={e => onChange(e.target.checked)}
      />
      <span className={`${styles.box} ${checked ? styles.checked : ''}`} aria-hidden>
        {checked && <span className={styles.mark} />}
      </span>
      <span>{children}</span>
    </label>
  )
}

import { useEffect, useId, useRef } from 'react'
import type { ReactNode } from 'react'
import styles from './Dialog.module.css'

interface DialogProps {
  open: boolean
  title: string
  onClose: () => void
  children: ReactNode
  actions?: ReactNode
}

export function Dialog({ open, title, onClose, children, actions }: DialogProps) {
  const titleId = useId()
  const onCloseRef = useRef(onClose)
  useEffect(() => { onCloseRef.current = onClose })

  useEffect(() => {
    if (!open) return
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onCloseRef.current() }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [open])

  if (!open) return null
  return (
    <div className={styles.overlay} role="dialog" aria-modal="true" aria-labelledby={titleId}>
      <div className={styles.body}>
        <h2 id={titleId} className={styles.title}>{title}</h2>
        <div className={styles.content}>{children}</div>
        {actions && <div className={styles.actions}>{actions}</div>}
      </div>
    </div>
  )
}

import { useTranslation } from 'react-i18next'
import styles from './ProgressLight.module.css'

export interface ProgressNode {
  question: string
  answer?: string
  answered: boolean
}

interface ProgressLightProps {
  title: string
  caption: string
  nodes: ProgressNode[]
  /** 目前所在題（0-based） */
  currentIndex: number
  /** 點擊「較早且已答」節點時觸發 */
  onJump: (index: number) => void
}

/** 探索進度：底部一條線上的 10 個節點；點擊較早已答節點可跳題，hover 顯示題目與回答。 */
export function ProgressLight({ title, caption, nodes, currentIndex, onJump }: ProgressLightProps) {
  const { t } = useTranslation()
  return (
    <div className={styles.wrapper} role="group" aria-label={`${title} ${caption}`}>
      <div className={styles.meta}>
        <span>{title}</span>
        <span>{caption}</span>
      </div>
      <div className={styles.track}>
        {nodes.map((node, index) => {
          const isCurrent = index === currentIndex
          const canJump = node.answered && index < currentIndex
          const state = isCurrent ? styles.nodeCurrent : node.answered ? styles.nodeAnswered : styles.nodeLocked
          return (
            <div key={index} className={styles.nodeWrap}>
              <button
                type="button"
                className={`${styles.node} ${state}`}
                disabled={!canJump}
                aria-current={isCurrent ? 'step' : undefined}
                aria-label={t(
                  node.answered ? 'exploration.progressNodeAnswered' : 'exploration.progressNodeUnanswered',
                  { n: index + 1 }
                )}
                onClick={() => canJump && onJump(index)}
              />
              {node.answered && (
                <div className={styles.tooltip} role="tooltip">
                  <div className={styles.tooltipQuestion}>{node.question}</div>
                  {node.answer && <div className={styles.tooltipAnswer}>{node.answer}</div>}
                </div>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

import type { ReactNode } from 'react'
import styles from './Scene.module.css'

type SceneVariant = 'center' | 'column' | 'scroll'

interface SceneProps {
  children: ReactNode
  variant?: SceneVariant
  /** 入口儀式使用較慢的進場 */
  slow?: boolean
  className?: string
}

/** 單一場景的容器：滿版、疊在沉浸舞台之上，帶統一的進場動畫。 */
export function Scene({ children, variant = 'center', slow, className }: SceneProps) {
  const classes = [styles.scene, styles[variant], slow ? styles.slow : '', className ?? '']
    .filter(Boolean)
    .join(' ')
  return <div className={classes}>{children}</div>
}

