import styles from './TextInput.module.css'

interface TextInputProps {
  value: string
  onChange: (value: string) => void
  placeholder?: string
  /** 單行時渲染 input，多行渲染 textarea */
  rows?: number
  autoFocus?: boolean
  ariaLabel?: string
  onEnter?: () => void
}

/** 單／多行文字輸入欄。探索頁的作答框另見 AnswerField。 */
export function TextInput({
  value,
  onChange,
  placeholder,
  rows = 1,
  autoFocus,
  ariaLabel,
  onEnter
}: TextInputProps) {
  if (rows <= 1) {
    return (
      <input
        className={`${styles.wrapper} ${styles.field}`}
        value={value}
        placeholder={placeholder}
        aria-label={ariaLabel ?? placeholder}
        autoFocus={autoFocus}
        onChange={e => onChange(e.target.value)}
        onKeyDown={e => {
          if (e.key === 'Enter' && onEnter) {
            e.preventDefault()
            onEnter()
          }
        }}
      />
    )
  }

  return (
    <textarea
      className={`${styles.wrapper} ${styles.field}`}
      value={value}
      placeholder={placeholder}
      aria-label={ariaLabel ?? placeholder}
      autoFocus={autoFocus}
      rows={rows}
      onChange={e => onChange(e.target.value)}
    />
  )
}

import styles from './ToggleSwitch.module.css'

interface ToggleSwitchProps {
  checked: boolean
  onChange: () => void
  ariaLabel: string
  className?: string
}

/**
 * 共用開關：造型參考 Material Design 3 的 Switch（軌道 + 滑動把手，
 * 開啟時把手放大並滑到右側），顏色改用本專案品牌色。
 * 語意採 role="switch" + aria-checked，供右上角動態開關與設定頁共用。
 */
export function ToggleSwitch({ checked, onChange, ariaLabel, className }: ToggleSwitchProps) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={ariaLabel}
      className={`${styles.track} ${checked ? styles.on : ''} ${className ?? ''}`}
      onClick={onChange}
    >
      <span className={styles.thumb} aria-hidden />
    </button>
  )
}

import { useTranslation } from 'react-i18next'
import { useSettings } from '@/contexts/SettingsContext'
import { ToggleSwitch } from '@/components/ui/ToggleSwitch'

/** 右上角動態效果開關（MD3 switch 造型）：切換全站 reduceMotion，並寫入設定（full / reduced）。 */
export function MotionToggle() {
  const { t } = useTranslation()
  const { reduceMotion, updateSettings } = useSettings()

  // reduceMotion 為 true 代表目前動態關閉，點擊要開啟 → 'full'
  const toggle = () => updateSettings({ motionMode: reduceMotion ? 'full' : 'reduced' })
  const label = reduceMotion ? t('motionToggle.off') : t('motionToggle.on')

  return <ToggleSwitch checked={!reduceMotion} onChange={toggle} ariaLabel={label} />
}

import { useEffect, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { seedDemoExploration } from '@/data/demo-seed'
import styles from './SceneMenu.module.css'

interface SceneEntry {
  labelKey: string
  resolve: () => string
}

/**
 * Demo 場景導覽（對應設計稿右上角的「場景 ▾」）。
 * 需要探索紀錄的場景會先寫入一筆示範資料，讓每個場景都能單獨展示。
 */
const SCENE_ENTRIES: SceneEntry[] = [
  { labelKey: 'sceneMenu.consent', resolve: () => '/consent' },
  { labelKey: 'sceneMenu.ritual', resolve: () => '/ritual' },
  { labelKey: 'sceneMenu.home', resolve: () => '/home' },
  { labelKey: 'sceneMenu.topic', resolve: () => '/topic' },
  {
    labelKey: 'sceneMenu.explore',
    resolve: () => `/explore/${seedDemoExploration('fresh').id}`
  },
  {
    labelKey: 'sceneMenu.exploreLast',
    // 使用「十題皆已作答」的示範資料，讓直接跳到第 10 題時，
    // 第 1～9 題節點皆為已完成狀態（hover 顯示題目與回答）。
    resolve: () => `/explore/${seedDemoExploration('answered').id}?q=10`
  },
  {
    labelKey: 'sceneMenu.settling',
    resolve: () => `/settle/${seedDemoExploration('answered').id}`
  },
  {
    labelKey: 'sceneMenu.summary',
    resolve: () => `/summary/${seedDemoExploration('answered').id}`
  },
  {
    labelKey: 'sceneMenu.gather',
    resolve: () => `/gather/${seedDemoExploration('completed').id}`
  },
  {
    labelKey: 'sceneMenu.card',
    resolve: () => `/card/${seedDemoExploration('completed').id}`
  },
  { labelKey: 'sceneMenu.history', resolve: () => '/history' },
  { labelKey: 'sceneMenu.settings', resolve: () => '/settings' }
]

export function SceneMenu() {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const [open, setOpen] = useState(false)
  const wrapperRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!open) return
    const onPointerDown = (event: MouseEvent) => {
      if (!wrapperRef.current?.contains(event.target as Node)) setOpen(false)
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false)
    }
    window.addEventListener('mousedown', onPointerDown)
    window.addEventListener('keydown', onKeyDown)
    return () => {
      window.removeEventListener('mousedown', onPointerDown)
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [open])

  const go = (path: string) => {
    setOpen(false)
    navigate(path)
  }

  return (
    <div className={styles.wrapper} ref={wrapperRef}>
      <button
        type="button"
        className={styles.trigger}
        onClick={() => setOpen(value => !value)}
        aria-expanded={open}
        aria-haspopup="menu"
      >
        {t('sceneMenu.trigger')}
      </button>
      {open && (
        <div className={styles.menu} role="menu">
          {SCENE_ENTRIES.map(entry => (
            <button
              key={entry.labelKey}
              type="button"
              role="menuitem"
              className={styles.item}
              onClick={() => go(entry.resolve())}
            >
              {t(entry.labelKey)}
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

