import { useCallback, useEffect, useRef, useState } from 'react'

export function useLocalStorage<T>(key: string, initial: T): [T, (value: T | ((prev: T) => T)) => void] {
  const initialRef = useRef(initial)

  const [value, setValue] = useState<T>(() => {
    try {
      const raw = localStorage.getItem(key)
      return raw === null ? initial : (JSON.parse(raw) as T)
    } catch {
      return initial
    }
  })

  // sync when key changes
  useEffect(() => {
    try {
      const raw = localStorage.getItem(key)
      setValue(raw === null ? initialRef.current : (JSON.parse(raw) as T))
    } catch {
      setValue(initialRef.current)
    }
  }, [key])

  useEffect(() => {
    try { localStorage.setItem(key, JSON.stringify(value)) } catch { /* ignore quota errors */ }
  }, [key, value])

  const update = useCallback((next: T | ((prev: T) => T)) => {
    setValue(prev => (typeof next === 'function' ? (next as (p: T) => T)(prev) : next))
  }, [])

  return [value, update]
}

import { useEffect, useState } from 'react'
import type { MotionMode } from '@/types'

const MEDIA_QUERY = '(prefers-reduced-motion: reduce)'

export function useReducedMotion(mode: MotionMode): boolean {
  const [systemReduced, setSystemReduced] = useState(() => {
    if (typeof window === 'undefined') return false
    return window.matchMedia(MEDIA_QUERY).matches
  })

  useEffect(() => {
    const mql = window.matchMedia(MEDIA_QUERY)
    const listener = (e: MediaQueryListEvent) => setSystemReduced(e.matches)
    mql.addEventListener('change', listener)
    return () => mql.removeEventListener('change', listener)
  }, [])

  if (mode === 'reduced') return true
  if (mode === 'full') return false
  return systemReduced
}

