import { useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Scene } from '@/components/ui/Scene'
import { Button } from '@/components/ui/Button'
import { useStageScene } from '@/components/stage/StageContext'
import { useSettings } from '@/contexts/SettingsContext'
import { findInProgress, listExplorations } from '@/storage/explorations'
import { TOPICS } from '@/data/topics'
import styles from './HomePage.module.css'

export function HomePage() {
  const { t } = useTranslation()
  const { settings } = useSettings()
  const navigate = useNavigate()

  useStageScene('cool')

  const draft = useMemo(() => findInProgress(), [])
  const hasHistory = useMemo(() => listExplorations().length > 0, [])
  // Demo 用：即使已有紀錄也能預覽第一次造訪的空狀態
  const [previewEmpty, setPreviewEmpty] = useState(false)
  const showEmpty = previewEmpty || !hasHistory

  const draftTopicLabel = draft
    ? draft.topicCustomLabel ??
      t(TOPICS.find(option => option.key === draft.topic)?.labelKey ?? 'topics.academics')
    : ''
  const draftQuestionNumber = draft ? Math.min(10, draft.answers.length + 1) : 0

  return (
    <Scene>
      <button
        type="button"
        className={styles.settings}
        aria-label={t('home.settings')}
        title={t('home.settings')}
        onClick={() => navigate('/settings')}
      >
        <svg width="20" height="20" viewBox="0 0 22 22" aria-hidden>
          <circle cx="11" cy="11" r="8" fill="none" stroke="rgba(255,255,255,.6)" strokeWidth="1.4" />
          <circle cx="11" cy="11" r="2.4" fill="rgba(255,255,255,.6)" />
        </svg>
      </button>

      <div className={styles.content}>
        {showEmpty ? (
          <p className={styles.emptyInvite}>
            {t('home.emptyInvite')}
            <span className={styles.emptyHighlight}>{t('home.emptyInviteHighlight')}</span>
            {t('home.emptyInviteTail')}
          </p>
        ) : (
          <>
            <p className={styles.greeting}>{t('home.greeting', { name: settings.studentName })}</p>
            <p className={styles.intro}>{t('home.intro')}</p>
          </>
        )}

        <div className={styles.primaryRow}>
          <Button onClick={() => navigate('/topic')}>{t('home.startExploring')}</Button>
          {!showEmpty && draft && (
            <Button
              variant="secondary"
              className={styles.resume}
              onClick={() => navigate(`/explore/${draft.id}`)}
            >
              {t('home.resume', {
                topic: draftTopicLabel,
                questionNumber: draftQuestionNumber
              })}
            </Button>
          )}
        </div>

        <div className={styles.footerRow}>
          <Button variant="link" onClick={() => navigate('/history')}>
            {t('home.viewHistory')}
          </Button>
          <Button variant="quiet" onClick={() => setPreviewEmpty(value => !value)}>
            {previewEmpty ? t('home.previewNormal') : t('home.previewEmpty')}
          </Button>
        </div>
      </div>
    </Scene>
  )
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Scene } from '@/components/ui/Scene'
import { Button } from '@/components/ui/Button'
import { TextInput } from '@/components/ui/TextInput'
import { useStageScene } from '@/components/stage/StageContext'
import { OTHER_TOPIC, TOPIC_CARDS } from '@/data/topics'
import type { TopicKey } from '@/types'
import { createExploration } from '@/storage/explorations'
import styles from './TopicSelectPage.module.css'

export function TopicSelectPage() {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const [customText, setCustomText] = useState('')

  useStageScene('cool', 'dawn')

  // 設計稿中選定議題即直接進入探索，因此每張卡就是一顆按鈕
  const start = (topic: TopicKey, customLabel?: string) => {
    const record = createExploration({ topic, topicCustomLabel: customLabel })
    navigate(`/explore/${record.id}`)
  }

  const startCustom = () => {
    const label = customText.trim()
    if (!label) return
    start(OTHER_TOPIC.key, label)
  }

  return (
    <Scene variant="column">
      <Button variant="text" className={styles.back} onClick={() => navigate('/home')}>
        {t('history.backHome')}
      </Button>

      <p className={styles.title}>{t('topics.prompt')}</p>
      <p className={styles.hint}>{t('topics.hint')}</p>

      <div className={styles.grid}>
        {TOPIC_CARDS.map(option => (
          <button
            key={option.key}
            type="button"
            className={styles.card}
            onClick={() => start(option.key)}
          >
            <span className={styles.cardLabel}>{t(option.labelKey)}</span>
            <span className={styles.cardDesc}>{t(option.descKey)}</span>
          </button>
        ))}

        <div className={styles.other}>
          <div className={styles.otherLabels}>
            <div className={styles.otherTitle}>{t('topics.other')}</div>
            <div className={styles.otherDesc}>{t('topics.otherDesc')}</div>
          </div>
          <div className={styles.otherField}>
            <TextInput
              value={customText}
              onChange={setCustomText}
              placeholder={t('topics.customPlaceholder')}
              onEnter={startCustom}
            />
          </div>
          <Button className={styles.otherStart} disabled={!customText.trim()} onClick={startCustom}>
            {t('topics.next')}
          </Button>
        </div>
      </div>
    </Scene>
  )
}

import { useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Scene } from '@/components/ui/Scene'
import { useStageScene } from '@/components/stage/StageContext'
import { useSettings } from '@/contexts/SettingsContext'
import styles from './SettlingPage.module.css'

const SETTLE_MS = 4600
const REDUCED_MS = 600

export function SettlingPage() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const { t } = useTranslation()
  const { reduceMotion } = useSettings()

  useStageScene('warm')

  const goToSummary = () => navigate(`/summary/${id}`)

  useEffect(() => {
    const timer = window.setTimeout(goToSummary, reduceMotion ? REDUCED_MS : SETTLE_MS)
    return () => window.clearTimeout(timer)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, reduceMotion])

  return (
    <Scene slow>
      <div className={styles.skipLayer} onClick={reduceMotion ? undefined : goToSummary}>
        <div className={styles.ring} aria-hidden />
        <div className={`${styles.ring} ${styles.ringDelayed}`} aria-hidden />
        <div className={styles.core} aria-hidden />
      </div>
      <p className={styles.line}>{t('settling.line1')}</p>
      {!reduceMotion && (
        <button type="button" className={styles.skipHint} onClick={goToSummary}>
          {t('transition.skip')}
        </button>
      )}
    </Scene>
  )
}

import { useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Scene } from '@/components/ui/Scene'
import { Button } from '@/components/ui/Button'
import { useStageScene } from '@/components/stage/StageContext'
import { ExplorationProvider, useExploration } from '@/contexts/ExplorationContext'
import { DEMO_SUMMARY, DEMO_CARD } from '@/data/demo-summary'
import { TOPICS } from '@/data/topics'
import type { SummarySection } from '@/types'
import styles from './SummaryPage.module.css'

/** 段落逐段揭露的間隔（秒），對應設計稿 animation-delay: i * 0.55s */
const REVEAL_STEP_SECONDS = 0.55

function SummaryBlock({ section, index }: { section: SummarySection; index: number }) {
  return (
    <div
      className={styles.section}
      style={{ animationDelay: `${(index * REVEAL_STEP_SECONDS).toFixed(2)}s` }}
    >
      <div className={styles.sectionTitle}>{section.title}</div>

      {section.resources ? (
        <div className={styles.resources}>
          {section.resources.map(resource => (
            <div key={resource.name} className={styles.resource}>
              <div className={styles.resourceHead}>
                <span className={styles.resourceName}>{resource.name}</span>
                <span className={styles.resourceType}>{resource.type}</span>
              </div>
              <p className={styles.resourceReason}>{resource.reason}</p>
              <a
                className={styles.resourceLink}
                href={resource.url}
                target="_blank"
                rel="noopener noreferrer"
              >
                {resource.url} ↗
              </a>
            </div>
          ))}
        </div>
      ) : section.items ? (
        <div className={styles.list}>
          {section.items.map(item => (
            <div key={item} className={styles.listItem}>
              <span className={styles.bullet} aria-hidden />
              <span className={styles.listText}>{item}</span>
            </div>
          ))}
        </div>
      ) : (
        <p className={styles.sectionBody}>{section.body}</p>
      )}
    </div>
  )
}

function SummaryInner() {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const { exploration, finish } = useExploration()

  useStageScene('warm')

  // 進入總結即固化這次探索的結果，讓歷史紀錄與匯出都有完整內容
  useEffect(() => {
    if (!exploration || exploration.status === 'completed') return
    const topicLabel =
      exploration.topicCustomLabel ??
      t(TOPICS.find(option => option.key === exploration.topic)?.labelKey ?? 'topics.academics')
    finish(DEMO_SUMMARY, {
      ...DEMO_CARD,
      topicLabel,
      date: new Date().toISOString().slice(0, 10)
    })
  }, [exploration, finish, t])

  if (!exploration) return <Scene>{t('history.notFound')}</Scene>

  return (
    <Scene variant="scroll">
      <div className={styles.inner}>
        <div className={styles.header}>
          <div className={styles.eyebrow}>{t('summary.eyebrow')}</div>
          <p className={styles.opening}>{t('summary.opening')}</p>
        </div>

        {DEMO_SUMMARY.map((section, index) => (
          <SummaryBlock key={section.key} section={section} index={index} />
        ))}

        <div className={styles.actions}>
          <Button onClick={() => navigate(`/gather/${exploration.id}`)}>
            {t('summary.continue')}
          </Button>
        </div>
      </div>
    </Scene>
  )
}

export function SummaryPage() {
  const { id } = useParams<{ id: string }>()
  if (!id) return null
  return (
    <ExplorationProvider id={id}>
      <SummaryInner />
    </ExplorationProvider>
  )
}

import { useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Scene } from '@/components/ui/Scene'
import { SelfAwarenessCard } from '@/components/cards/SelfAwarenessCard'
import { useStageScene } from '@/components/stage/StageContext'
import { useSettings } from '@/contexts/SettingsContext'
import { getExploration } from '@/storage/explorations'
import styles from './GatherPage.module.css'

const GATHER_MS = 3100
const REDUCED_MS = 500

/** 凝聚成卡的過場：光環收束、卡片由小放大並翻面。可點擊任意處跳過。 */
export function GatherPage() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const { t } = useTranslation()
  const { reduceMotion } = useSettings()
  const exploration = id ? getExploration(id) : null

  useStageScene('warm')

  const goToCard = () => navigate(`/card/${id}`, { replace: true })

  useEffect(() => {
    const timer = window.setTimeout(goToCard, reduceMotion ? REDUCED_MS : GATHER_MS)
    return () => window.clearTimeout(timer)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, reduceMotion])

  return (
    <Scene>
      <div className={styles.skipLayer} onClick={reduceMotion ? undefined : goToCard}>
        <div className={styles.ring} aria-hidden />
        <div className={`${styles.ring} ${styles.ringDelayed}`} aria-hidden />
        <div className={styles.core} aria-hidden />
        <div className={styles.cardSlot} aria-hidden>
          <div className={styles.flipper}>
            <div className={`${styles.face} ${styles.faceFront}`} />
            <div className={`${styles.face} ${styles.faceBack}`}>
              {exploration?.card && <SelfAwarenessCard data={exploration.card} />}
            </div>
          </div>
        </div>
      </div>
      <p className={styles.hint}>{t('gather.hint')}</p>
      {!reduceMotion && (
        <button type="button" className={styles.skipHint} onClick={goToCard}>
          {t('transition.skip')}
        </button>
      )}
    </Scene>
  )
}

import { useRef } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Scene } from '@/components/ui/Scene'
import { SelfAwarenessCard } from '@/components/cards/SelfAwarenessCard'
import { Button } from '@/components/ui/Button'
import { useToast } from '@/components/ui/Toast'
import { useStageScene } from '@/components/stage/StageContext'
import { ExplorationProvider, useExploration } from '@/contexts/ExplorationContext'
import { exportNodeAsPng } from '@/services/exportPng'
import { exportExplorationAsXlsx } from '@/services/exportXlsx'
import { APPOINTMENT_URL } from '@/constants/urls'
import styles from './CardPage.module.css'

function CardInner() {
  const { t } = useTranslation()
  const { exploration } = useExploration()
  const { showToast } = useToast()
  const navigate = useNavigate()
  const cardRef = useRef<HTMLDivElement>(null)

  useStageScene('warm')

  if (!exploration?.card) return <Scene>{t('history.notFound')}</Scene>

  const filenameBase = `learning-exploration-${exploration.card.date}`

  const exportPng = () => {
    if (!cardRef.current) return
    exportNodeAsPng(cardRef.current, `${filenameBase}.png`).catch(error => {
      console.error('[export]', error)
      showToast(t('card.exportFailed'))
    })
  }

  const exportReport = () => {
    try {
      exportExplorationAsXlsx(exploration, `${filenameBase}.xlsx`)
    } catch (error) {
      console.error('[export]', error)
      showToast(t('card.exportFailed'))
    }
  }

  return (
    <Scene variant="scroll">
      <div className={styles.inner}>
        <div className={styles.cardFrame}>
          <SelfAwarenessCard data={exploration.card} ref={cardRef} />
        </div>

        <div className={styles.actions}>
          <Button onClick={() => window.open(APPOINTMENT_URL, '_blank', 'noopener,noreferrer')}>
            {t('card.bookAppointment')}
          </Button>
          <Button variant="secondary" onClick={exportReport}>
            {t('card.exportReport')}
          </Button>
        </div>

        <Button variant="text" className={styles.exportCard} onClick={exportPng}>
          {t('card.exportCard')}
        </Button>

        <Button variant="link" className={styles.backHome} onClick={() => navigate('/home')}>
          {t('card.backHome')}
        </Button>
      </div>
    </Scene>
  )
}

export function CardPage() {
  const { id } = useParams<{ id: string }>()
  if (!id) return null
  return (
    <ExplorationProvider id={id}>
      <CardInner />
    </ExplorationProvider>
  )
}

import { useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Scene } from '@/components/ui/Scene'
import { Button } from '@/components/ui/Button'
import { useStageScene } from '@/components/stage/StageContext'
import { listExplorations } from '@/storage/explorations'
import { TOPICS } from '@/data/topics'
import styles from './HistoryListPage.module.css'

function formatStamp(iso: string): { date: string; time: string } {
  const value = new Date(iso)
  if (Number.isNaN(value.getTime())) return { date: iso.slice(0, 10), time: '' }
  const pad = (input: number) => String(input).padStart(2, '0')
  return {
    date: `${value.getFullYear()}.${pad(value.getMonth() + 1)}.${pad(value.getDate())}`,
    time: `${pad(value.getHours())}:${pad(value.getMinutes())}`
  }
}

export function HistoryListPage() {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const records = useMemo(() => listExplorations(), [])
  // Demo 用：即使已有紀錄也能預覽空狀態
  const [previewEmpty, setPreviewEmpty] = useState(false)
  const showEmpty = previewEmpty || records.length === 0

  useStageScene('cool')

  return (
    <Scene variant="scroll">
      <Button variant="text" className={styles.back} onClick={() => navigate('/home')}>
        {t('history.backHome')}
      </Button>

      <div className={styles.inner}>
        <p className={styles.title}>{t('history.title')}</p>
        <p className={styles.subtitle}>{t('history.subtitle')}</p>

        {showEmpty ? (
          <div className={styles.empty}>
            <p className={styles.emptyText}>{t('history.empty')}</p>
          </div>
        ) : (
          <div className={styles.list}>
            {records.map(record => {
              const { date, time } = formatStamp(record.updatedAt)
              const topicLabel =
                record.topicCustomLabel ??
                t(TOPICS.find(option => option.key === record.topic)?.labelKey ?? record.topic)
              return (
                <button
                  key={record.id}
                  type="button"
                  className={styles.item}
                  onClick={() => navigate(`/history/${record.id}`)}
                >
                  <span className={styles.itemHead}>
                    <span className={styles.itemDate}>
                      {date}
                      {time && ` · ${time}`}
                    </span>
                    <span className={styles.itemTopic}>{topicLabel}</span>
                  </span>
                  <span className={styles.itemInsight}>
                    {record.card?.coreInsight ?? t('history.openDetail')}
                  </span>
                </button>
              )
            })}
          </div>
        )}

        {records.length > 0 && (
          <div className={styles.toggleRow}>
            <Button variant="quiet" onClick={() => setPreviewEmpty(value => !value)}>
              {previewEmpty ? t('history.previewRecords') : t('history.previewEmpty')}
            </Button>
          </div>
        )}
      </div>
    </Scene>
  )
}

import { useMemo } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Scene } from '@/components/ui/Scene'
import { Button } from '@/components/ui/Button'
import { useToast } from '@/components/ui/Toast'
import { useStageScene } from '@/components/stage/StageContext'
import { getExploration } from '@/storage/explorations'
import { DEMO_QUESTIONS } from '@/data/demo-dialogue'
import { TOPICS } from '@/data/topics'
import { exportExplorationAsXlsx } from '@/services/exportXlsx'
import { APPOINTMENT_URL } from '@/constants/urls'
import type { SummarySection } from '@/types'
import styles from './HistoryDetailPage.module.css'

function SummaryRecord({ section }: { section: SummarySection }) {
  return (
    <div className={styles.summaryBlock}>
      <div className={styles.summaryTitle}>{section.title}</div>
      {section.resources ? (
        <div className={styles.summaryList}>
          {section.resources.map(resource => (
            <div key={resource.name} className={styles.resourceLine}>
              {resource.name} —{' '}
              <a
                className={styles.resourceLink}
                href={resource.url}
                target="_blank"
                rel="noopener noreferrer"
              >
                {resource.url}
              </a>
            </div>
          ))}
        </div>
      ) : section.items ? (
        <div className={styles.summaryList}>
          {section.items.map(item => (
            <div key={item} className={styles.summaryItem}>
              <span className={styles.bullet} aria-hidden />
              <span className={styles.summaryItemText}>{item}</span>
            </div>
          ))}
        </div>
      ) : (
        <p className={styles.summaryText}>{section.body}</p>
      )}
