export function HistoryDetailPage() {
  const { t } = useTranslation()
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const { showToast } = useToast()
  const record = useMemo(() => (id ? getExploration(id) : null), [id])

  useStageScene('mid')

  if (!record) return <Scene>{t('history.notFound')}</Scene>

  const stamp = new Date(record.updatedAt)
  const pad = (input: number) => String(input).padStart(2, '0')
  const dateLabel = Number.isNaN(stamp.getTime())
    ? record.updatedAt.slice(0, 10)
    : `${stamp.getFullYear()}.${pad(stamp.getMonth() + 1)}.${pad(stamp.getDate())} · ${pad(
        stamp.getHours()
      )}:${pad(stamp.getMinutes())}`
  const topicLabel =
    record.topicCustomLabel ??
    t(TOPICS.find(option => option.key === record.topic)?.labelKey ?? record.topic)

  const exportReport = () => {
    try {
      exportExplorationAsXlsx(record, `learning-exploration-${record.updatedAt.slice(0, 10)}.xlsx`)
    } catch (error) {
      console.error('[export]', error)
      showToast(t('card.exportFailed'))
    }
  }

  return (
    <Scene variant="scroll">
      <Button variant="text" className={styles.back} onClick={() => navigate('/history')}>
        {t('history.back')}
      </Button>

      <div className={styles.inner}>
        <div className={styles.head}>
          <span className={styles.stamp}>{dateLabel}</span>
          <span className={styles.topic}>{topicLabel}</span>
        </div>
        <p className={styles.insight}>{record.card?.coreInsight ?? t('history.detailTitle')}</p>

        <div className={styles.sectionLabel}>{t('history.questions')}</div>
        <div className={styles.qaList}>
          {DEMO_QUESTIONS.map(question => {
            const answer = record.answers.find(item => item.questionIndex === question.index)
            return (
              <div key={question.index} className={styles.qaItem}>
                <p className={styles.qaReflection}>{question.empathy}</p>
                <p className={styles.qaQuestion}>
                  <span className={styles.qaNumber}>Q{question.index + 1}.</span> {question.question}
                </p>
                <div className={styles.qaAnswer}>{answer?.text?.trim() || '—'}</div>
              </div>
            )
          })}
        </div>

        {record.summary && (
          <>
            <div className={styles.sectionLabel}>{t('history.summarySection')}</div>
            {record.summary.map(section => (
              <SummaryRecord key={section.key} section={section} />
            ))}
          </>
        )}

        <div className={styles.actions}>
          <Button onClick={() => window.open(APPOINTMENT_URL, '_blank', 'noopener,noreferrer')}>
            {t('card.bookAppointment')}
          </Button>
          <Button variant="secondary" onClick={exportReport}>
            {t('card.exportReportXls')}
          </Button>
        </div>
      </div>
    </Scene>
  )
}

import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Scene } from '@/components/ui/Scene'
import { Button } from '@/components/ui/Button'
import { TextInput } from '@/components/ui/TextInput'
import { ToggleSwitch } from '@/components/ui/ToggleSwitch'
import { useStageScene } from '@/components/stage/StageContext'
import { useSettings } from '@/contexts/SettingsContext'
import type { Locale } from '@/types'
import styles from './SettingsPage.module.css'

const APP_VERSION = 'v1.0.0'

const LOCALE_OPTIONS: { value: Locale; labelKey: string }[] = [
  { value: 'zh-TW', labelKey: 'settings.languageZh' },
  { value: 'en', labelKey: 'settings.languageEn' }
]

export function SettingsPage() {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const { settings, updateSettings, reduceMotion } = useSettings()

  useStageScene('mid')

  return (
    <Scene variant="scroll">
      <Button variant="text" className={styles.back} onClick={() => navigate('/home')}>
        {t('settings.back')}
      </Button>

      <div className={styles.inner}>
        <p className={styles.title}>{t('settings.title')}</p>

        <div className={styles.rows}>
          <div className={styles.row}>
            <span className={styles.label}>{t('settings.language')}</span>
            <div className={styles.segmented} role="group" aria-label={t('settings.language')}>
              {LOCALE_OPTIONS.map(option => (
                <button
                  key={option.value}
                  type="button"
                  className={`${styles.segment} ${
                    settings.locale === option.value ? styles.segmentActive : ''
                  }`}
                  aria-pressed={settings.locale === option.value}
                  onClick={() => updateSettings({ locale: option.value })}
                >
                  {t(option.labelKey)}
                </button>
              ))}
            </div>
          </div>

          <div className={styles.row}>
            <span className={styles.label}>{t('settings.motion')}</span>
            <ToggleSwitch
              checked={!reduceMotion}
              onChange={() => updateSettings({ motionMode: reduceMotion ? 'full' : 'reduced' })}
              ariaLabel={t('settings.motion')}
            />
          </div>

          <div className={styles.rowStacked}>
            <span className={styles.label}>
              {t('settings.typingSpeed')}
              {reduceMotion && <em className={styles.disabledNote}> {t('settings.typingSpeedDisabled')}</em>}
            </span>
            <div className={styles.sliderRow}>
              <span className={styles.sliderEnd}>{t('settings.typingSpeedFast')}</span>
              <input
                type="range"
                className={styles.slider}
                min={10}
                max={100}
                step={5}
                value={settings.typingSpeedMs}
                disabled={reduceMotion}
                aria-label={t('settings.typingSpeed')}
                aria-valuetext={t('settings.typingSpeedValue', { ms: settings.typingSpeedMs })}
                onChange={e => updateSettings({ typingSpeedMs: Number(e.target.value) })}
              />
              <span className={styles.sliderEnd}>{t('settings.typingSpeedSlow')}</span>
            </div>
            <div className={styles.sliderValue}>{t('settings.typingSpeedValue', { ms: settings.typingSpeedMs })}</div>
          </div>

          <div className={styles.rowStacked}>
            <span className={styles.label}>{t('settings.name')}</span>
            <div className={styles.nameField}>
              <TextInput
                value={settings.studentName}
                onChange={value => updateSettings({ studentName: value })}
                ariaLabel={t('settings.name')}
              />
            </div>
          </div>

          <div className={styles.row}>
            <span className={styles.label}>{t('settings.version')}</span>
            <span className={styles.value}>{APP_VERSION}</span>
          </div>

          <div className={`${styles.rowStacked} ${styles.rowLast}`}>
            <div className={styles.supportTitle}>{t('settings.support')}</div>
            <div className={styles.supportList}>
              <div className={styles.supportRow}>
                <span className={styles.supportLabel}>{t('settings.supportEmailLabel')}</span>
                <a href={`mailto:${t('settings.supportEmail')}`}>{t('settings.supportEmail')}</a>
              </div>
              <div className={styles.supportRow}>
                <span className={styles.supportLabel}>{t('settings.supportPhoneLabel')}</span>
                <span>{t('settings.supportPhone')}</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Scene>
  )
}

