import { computed, onUnmounted, ref, watch, type Ref } from 'vue'

interface Options {
  text: Ref<string> | (() => string)
  charsPerTick?: number
  tickMs?: Ref<number> | (() => number) | number
  enabled?: Ref<boolean> | (() => boolean) | boolean
}

function toGetter<T>(source: Ref<T> | (() => T) | T): () => T {
  if (typeof source === 'function') return source as () => T
  if (source && typeof source === 'object' && 'value' in (source as object)) {
    return () => (source as Ref<T>).value
  }
  return () => source as T
}

/**
 * 逐字揭示。整段文字由呼叫端一開始就渲染，本 composable 只回報「已揭示的字數」。
 * 揭示計時器由單一 watch 擁有並在完成時自我清除。
 */
export function useTypewriter({
  text,
  charsPerTick = 1,
  tickMs = 30,
  enabled = true
}: Options): { displayed: Ref<string>; done: Ref<boolean>; skip: () => void } {
  const getText = toGetter(text)
  const getTickMs = toGetter(tickMs)
  const getEnabled = toGetter(enabled)

  const count = ref(getEnabled() ? 0 : getText().length)
  let intervalId: number | null = null

  const clear = () => {
    if (intervalId !== null) {
      window.clearInterval(intervalId)
      intervalId = null
    }
  }

  const restart = () => {
    clear()
    const currentText = getText()

    if (!getEnabled()) {
      count.value = currentText.length
      return
    }

    count.value = 0
    if (currentText.length === 0) return

    intervalId = window.setInterval(() => {
      const next = Math.min(currentText.length, count.value + charsPerTick)
      count.value = next
      if (next >= currentText.length) clear()
    }, getTickMs())
  }

  watch([getText, getEnabled, getTickMs], restart, { immediate: true })

  onUnmounted(clear)

  const skip = () => {
    clear()
    count.value = getText().length
  }

  return {
    displayed: computed(() => getText().slice(0, count.value)),
    done: computed(() => count.value >= getText().length),
    skip
  }
}

