      if (next >= currentText.length) clear()
    }, getTickMs())
  }

  watch([getText, getEnabled, getTickMs], restart, { immediate: true })

  onUnmounted(clear)

  const skip = () => {
    clear()
    count.value = getText().length
  }

  return {
    displayed: computed(() => getText().slice(0, count.value)),
    done: computed(() => count.value >= getText().length),
    skip
  }
}

