export function useAutosave<T>(value: Ref<T>, save: (value: T) => void, delayMs = 400): { flush: () => void } {
  let timerId: number | null = null
  let latestSave = save

  watch(
    () => save,
    next => { latestSave = next }
  )

  const clear = () => {
    if (timerId !== null) {
      window.clearTimeout(timerId)
      timerId = null
    }
  }

  watch(
    value,
    next => {
      clear()
      timerId = window.setTimeout(() => latestSave(next), delayMs)
    },
    { deep: true }
  )

  onUnmounted(clear)

  return {
    flush: () => {
      clear()
      latestSave(value.value)
    }
  }
}

