import { ref, watch, type Ref } from 'vue'

function read<T>(key: string, initial: T): T {
  try {
    const raw = localStorage.getItem(key)
    return raw === null ? initial : (JSON.parse(raw) as T)
  } catch {
    return initial
  }
}

export function useLocalStorage<T>(key: string, initial: T): [Ref<T>, (value: T | ((prev: T) => T)) => void] {
  const value = ref(read(key, initial)) as Ref<T>

  watch(
    () => key,
    () => { value.value = read(key, initial) }
  )

  watch(
    value,
    next => {
      try {
        localStorage.setItem(key, JSON.stringify(next))
      } catch {
        // ignore quota errors
      }
    },
    { deep: true }
  )

  const update = (next: T | ((prev: T) => T)) => {
    value.value = typeof next === 'function' ? (next as (p: T) => T)(value.value) : next
  }

  return [value, update]
}

