import { computed, onUnmounted, ref, type ComputedRef, type Ref } from 'vue'
import type { MotionMode } from '@/types'

const MEDIA_QUERY = '(prefers-reduced-motion: reduce)'

export function useReducedMotion(mode: Ref<MotionMode>): ComputedRef<boolean> {
  const systemReduced = ref(
    typeof window === 'undefined' ? false : window.matchMedia(MEDIA_QUERY).matches
  )

  if (typeof window !== 'undefined') {
    const mql = window.matchMedia(MEDIA_QUERY)
    const listener = (e: MediaQueryListEvent) => { systemReduced.value = e.matches }
    mql.addEventListener('change', listener)
    onUnmounted(() => mql.removeEventListener('change', listener))
  }

  return computed(() => {
    if (mode.value === 'reduced') return true
    if (mode.value === 'full') return false
    return systemReduced.value
  })
}

