import { inject, provide, ref, watchEffect, type InjectionKey, type Ref } from 'vue'

/** 光的色溫階段：冷（過去·契機）→ 中（現在·內在狀態）→ 暖（未來·前行） */
export type StageTone = 'cool' | 'mid' | 'warm'

/** 實景背景照片；null 表示只以漸層光斑呈現 */
export type StageBackdrop = 'dawn' | 'day' | 'sunset' | 'night'

export interface StageScene {
  tone: StageTone
  backdrop: StageBackdrop | null
  /** 實景照片主導的場景會關閉漸層光斑，避免兩層顏色互相打架 */
  dimGlow: boolean
}

export const DEFAULT_STAGE_SCENE: StageScene = { tone: 'cool', backdrop: null, dimGlow: false }

interface StageContextValue {
  scene: Ref<StageScene>
  setScene: (scene: StageScene) => void
}

const StageKey: InjectionKey<StageContextValue> = Symbol('Stage')

export function provideStage(): StageContextValue {
  const scene = ref<StageScene>({ ...DEFAULT_STAGE_SCENE })

  const setScene = (next: StageScene) => {
    const prev = scene.value
    if (prev.tone === next.tone && prev.backdrop === next.backdrop && prev.dimGlow === next.dimGlow) return
    scene.value = next
  }

  const value: StageContextValue = { scene, setScene }
  provide(StageKey, value)
  return value
}

export function useStage(): StageContextValue {
  const ctx = inject(StageKey)
  if (!ctx) throw new Error('useStage must be used within a component tree that called provideStage()')
  return ctx
}

/**
 * 由場景頁面宣告自己需要的舞台狀態。
 */
export function useStageScene(
  tone: StageTone | (() => StageTone),
  backdrop: StageBackdrop | null | (() => StageBackdrop | null) = null,
  dimGlow: boolean | (() => boolean) = false
): void {
  const { setScene } = useStage()
  watchEffect(() => {
    setScene({
      tone: typeof tone === 'function' ? tone() : tone,
      backdrop: typeof backdrop === 'function' ? backdrop() : backdrop,
      dimGlow: typeof dimGlow === 'function' ? dimGlow() : dimGlow
    })
  })
}

