import { computed, inject, provide, ref, watchEffect, type ComputedRef, type InjectionKey, type Ref } from 'vue'
import type { Settings } from '@/types'
import { readSettings, writeSettings } from '@/storage/settings'
import { useReducedMotion } from './useReducedMotion'
import { i18n } from '@/i18n'

interface SettingsContextValue {
  settings: Ref<Settings>
  updateSettings: (patch: Partial<Settings>) => void
  reduceMotion: ComputedRef<boolean>
}

const SettingsKey: InjectionKey<SettingsContextValue> = Symbol('Settings')

export function provideSettings(): SettingsContextValue {
  const base = readSettings()
  const settings = ref<Settings>(
    import.meta.env.MODE === 'test' ? { ...base, motionMode: 'reduced' } : base
  ) as Ref<Settings>

  watchEffect(() => {
    if (i18n.global.locale.value !== settings.value.locale) {
      i18n.global.locale.value = settings.value.locale
    }
    document.documentElement.setAttribute('lang', settings.value.locale === 'en' ? 'en' : 'zh-Hant-TW')
  })

  const updateSettings = (patch: Partial<Settings>) => {
    writeSettings(patch)
    settings.value = { ...settings.value, ...patch }
  }

  const motionMode = computed(() => settings.value.motionMode)
  const reduceMotion = useReducedMotion(motionMode)

  const value: SettingsContextValue = { settings, updateSettings, reduceMotion }
  provide(SettingsKey, value)
  return value
}

export function useSettings(): SettingsContextValue {
  const ctx = inject(SettingsKey)
  if (!ctx) throw new Error('useSettings must be used within a component tree that called provideSettings()')
  return ctx
}

