import { describe, it, expect, beforeAll, beforeEach, vi } from 'vitest'
import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { createMemoryRouter, RouterProvider } from 'react-router-dom'
import i18next from 'i18next'
import { SettingsProvider } from '@/contexts/SettingsContext'
import { routes } from '@/router'
import '@/i18n'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

function renderApp(initialPath = '/consent') {
  const testRouter = createMemoryRouter(routes, { initialEntries: [initialPath] })
  return render(
    <SettingsProvider>
      <RouterProvider router={testRouter} />
    </SettingsProvider>
  )
}

/**
 * 一律透過 i18n key 取文字，而非寫死中文字面值，
 * 這樣調整文案時不會連帶弄壞這支測試。
 */
const label = (key: string) => i18next.t(key)

beforeAll(async () => {
  // Ensure i18next is fully initialised before any test runs
  if (!i18next.isInitialized) {
    await new Promise<void>(resolve => {
      i18next.on('initialized', resolve)
    })
  }
})

describe('happy path', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it(
    'user can consent, enter the ritual, pick a topic, answer 10 questions, and reach the card',
    async () => {
      const user = userEvent.setup()
      renderApp('/consent')

      // ── 條款同意 ────────────────────────────────────────────────
      const checkbox = await screen.findByRole('checkbox')
      await user.click(checkbox)
      await user.click(screen.getByRole('button', { name: label('consent.next') }))

      // ── 入口儀式 ────────────────────────────────────────────────
      await user.click(await screen.findByRole('button', { name: label('ritual.continue') }))

      // ── 首頁 ────────────────────────────────────────────────────
      await user.click(await screen.findByRole('button', { name: label('home.startExploring') }))

      // ── 議題選擇：點卡片即開始 ──────────────────────────────────
      const topicCards = await screen.findAllByRole('button', {
        name: new RegExp(label('topics.career'))
      })
      await user.click(topicCards[0])

      // ── 一題一幕探索：反映段 → 提問段 → 作答 ────────────────────
      for (let index = 0; index < 10; index += 1) {
        // 減弱動效下揭字立即完成，點擊反映段即進入提問
        await user.click(await screen.findByText(label('exploration.continueHint')))

        const textbox = await screen.findByRole('textbox', { name: label('exploration.inputLabel') })
        await user.clear(textbox)
        await user.type(textbox, `answer ${index}`)

        const submitKey = index === 9 ? 'exploration.finish' : 'exploration.next'
        await user.click(screen.getByRole('button', { name: label(submitKey) }))
      }

      // ── 沉澱過場（減弱動效 → 600 ms 自動導向）→ 總結 ────────────
      await waitFor(() => expect(screen.getByText(label('summary.eyebrow'))).toBeInTheDocument(), {
        timeout: 8000
      })

      await user.click(
        await screen.findByRole('button', { name: label('summary.continue') }, { timeout: 8000 })
      )

      // ── 凝聚成卡過場 → 自我察覺卡 ───────────────────────────────
      await waitFor(
        () =>
          expect(
            screen.getByRole('button', { name: label('card.bookAppointment') })
          ).toBeInTheDocument(),
        { timeout: 12000 }
      )
      expect(screen.getAllByRole('img', { name: label('card.title') }).length).toBeGreaterThan(0)
    },
    40000
  )
})

import { describe, it, expect, beforeEach, beforeAll, vi } from 'vitest'
import { render, screen, act } from '@testing-library/react'
import { createMemoryRouter, RouterProvider } from 'react-router-dom'
import i18next from 'i18next'
import { SettingsProvider } from '@/contexts/SettingsContext'
import { seedDemoExploration } from '@/data/demo-seed'
import { routes } from '@/router'
import '@/i18n'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true, configurable: true,
    value: vi.fn().mockImplementation((q: string) => ({
      matches: false, media: q, onchange: null,
      addEventListener: vi.fn(), removeEventListener: vi.fn(),
      addListener: vi.fn(), removeListener: vi.fn(), dispatchEvent: vi.fn()
    }))
  })
}

beforeAll(async () => {
  if (!i18next.isInitialized) await new Promise<void>(r => i18next.on('initialized', () => r()))
})

describe('jump to question via ?q while already on an exploration', () => {
  beforeEach(() => { localStorage.clear(); stubMatchMedia() })

  it('remounts and honors ?q=10 when navigating between explorations', async () => {
    const a = seedDemoExploration('fresh')      // 起點：另一筆探索（第 1 題）
    const b = seedDemoExploration('answered')    // 目標：十題皆已作答
    const router = createMemoryRouter(routes, { initialEntries: [`/explore/${a.id}`] })
    render(
      <SettingsProvider>
        <RouterProvider router={router} />
      </SettingsProvider>
    )

    // 起點在第 1 題的反映階段（沒有題號計數器）
    expect(screen.queryByText('10')).not.toBeInTheDocument()

    // 探索中途「直接跳到第 10 題」：導覽到另一筆探索並帶 ?q=10
    await act(async () => {
      await router.navigate(`/explore/${b.id}?q=10`)
    })

    // 修正後：子樹重新掛載、依 ?q=10 進入第 10 題（問題階段顯示題號 10）
    expect(await screen.findByText('10')).toBeInTheDocument()
  })
})

