import { describe, it, expect, beforeEach, vi } from 'vitest'
import { renderHook } from '@testing-library/react'
import { useReducedMotion } from '@/hooks/useReducedMotion'

function stubMatchMedia(prefersReduced: boolean) {
  window.matchMedia = vi.fn().mockImplementation(query => ({
    matches: query === '(prefers-reduced-motion: reduce)' ? prefersReduced : false,
    media: query,
    onchange: null,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    addListener: vi.fn(),
    removeListener: vi.fn(),
    dispatchEvent: vi.fn()
  }))
}

describe('useReducedMotion', () => {
  beforeEach(() => {
    stubMatchMedia(false)
  })

  it('returns false when motionMode="system" and system prefers full motion', () => {
    const { result } = renderHook(() => useReducedMotion('system'))
    expect(result.current).toBe(false)
  })

  it('returns true when motionMode="system" and system prefers reduced motion', () => {
    stubMatchMedia(true)
    const { result } = renderHook(() => useReducedMotion('system'))
    expect(result.current).toBe(true)
  })

  it('returns true when motionMode="reduced" regardless of system', () => {
    stubMatchMedia(false)
    const { result } = renderHook(() => useReducedMotion('reduced'))
    expect(result.current).toBe(true)
  })

  it('returns false when motionMode="full" regardless of system', () => {
    stubMatchMedia(true)
    const { result } = renderHook(() => useReducedMotion('full'))
    expect(result.current).toBe(false)
  })

  it('removes event listener on unmount', () => {
    const addSpy = vi.fn()
    const removeSpy = vi.fn()
    window.matchMedia = vi.fn().mockReturnValue({
      matches: false,
      media: '(prefers-reduced-motion: reduce)',
      onchange: null,
      addEventListener: addSpy,
      removeEventListener: removeSpy,
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    })
