import { describe, it, expect, beforeAll } from 'vitest'
import i18n from '@/i18n'

describe('i18n', () => {
  beforeAll(async () => {
    if (!i18n.isInitialized) await i18n.init()
  })

  it('defaults to zh-TW', () => {
    expect(i18n.language).toBe('zh-TW')
  })

  it('resolves a known key in zh-TW', () => {
    expect(i18n.t('home.startExploring')).toBe('開始探索')
  })

  it('resolves the same key in English after change', async () => {
    await i18n.changeLanguage('en')
    expect(i18n.t('home.startExploring')).toBe('Start exploring')
    await i18n.changeLanguage('zh-TW')
  })

  it('has parallel keys for both locales', () => {
    const zh = i18n.getResourceBundle('zh-TW', 'translation')
    const en = i18n.getResourceBundle('en', 'translation')
    const flatten = (o: Record<string, unknown>, prefix = ''): string[] =>
      Object.entries(o).flatMap(([k, v]) =>
        typeof v === 'object' && v !== null
          ? flatten(v as Record<string, unknown>, `${prefix}${k}.`)
          : [`${prefix}${k}`]
      )
    const zhKeys = flatten(zh).sort()
    const enKeys = flatten(en).sort()
    expect(enKeys).toEqual(zhKeys)
  })

  it('interpolates variables correctly', () => {
    i18n.changeLanguage('zh-TW')
    expect(i18n.t('home.greeting', { name: '小明' })).toBe('小明，歡迎回來。')
  })
})

