import { describe, it, expect, beforeEach } from 'vitest'
import {
  listExplorations,
  createExploration,
  updateExploration,
  getExploration,
  findInProgress,
  deleteExploration
} from '@/storage/explorations'
import type { Exploration } from '@/types'

describe('exploration storage', () => {
  beforeEach(() => {
    localStorage.clear()
  })

  it('lists empty by default', () => {
    expect(listExplorations()).toEqual([])
  })

  it('creates an exploration and returns the record', () => {
    const rec = createExploration({ topic: 'career' })
    expect(rec.id).toBeTruthy()
    expect(rec.status).toBe('in-progress')
    expect(rec.topic).toBe('career')
    expect(rec.answers).toEqual([])
    expect(rec.createdAt).toBeTruthy()
    expect(rec.updatedAt).toBe(rec.createdAt)
  })

  it('lists created explorations newest first', async () => {
    const a = createExploration({ topic: 'career' })
    await new Promise(r => setTimeout(r, 5))
    const b = createExploration({ topic: 'academics' })
    const list = listExplorations()
    expect(list.map((r: Exploration) => r.id)).toEqual([b.id, a.id])
  })

  it('updates fields and bumps updatedAt', async () => {
    const rec = createExploration({ topic: 'career' })
    await new Promise(r => setTimeout(r, 5))
    const updated = updateExploration(rec.id, { status: 'completed' })
    expect(updated.status).toBe('completed')
    expect(new Date(updated.updatedAt).getTime())
      .toBeGreaterThan(new Date(rec.createdAt).getTime())
  })

  it('appends an answer via updateExploration', () => {
    const rec = createExploration({ topic: 'career' })
    const answered = updateExploration(rec.id, {
      answers: [{ questionIndex: 0, text: 'hello', updatedAt: new Date().toISOString() }]
    })
    expect(answered.answers).toHaveLength(1)
    expect(answered.answers[0].text).toBe('hello')
  })

  it('findInProgress returns the newest in-progress record', () => {
    createExploration({ topic: 'career' })
    const b = createExploration({ topic: 'academics' })
    updateExploration(b.id, { status: 'completed' })
    const inp = findInProgress()
    expect(inp?.topic).toBe('career')
  })

  it('getExploration returns null when not found', () => {
    expect(getExploration('missing')).toBeNull()
  })

  it('deleteExploration removes the record', () => {
    const rec = createExploration({ topic: 'career' })
    deleteExploration(rec.id)
    expect(getExploration(rec.id)).toBeNull()
  })

  it('throws when updating a non-existent id', () => {
    expect(() => updateExploration('missing', { status: 'completed' })).toThrow()
  })
})

import { describe, it, expect, beforeEach } from 'vitest'
import { readSettings, writeSettings, DEFAULT_SETTINGS } from '@/storage/settings'

describe('settings storage', () => {
  beforeEach(() => {
    localStorage.clear()
  })

  it('returns defaults when nothing stored', () => {
    expect(readSettings()).toEqual(DEFAULT_SETTINGS)
  })

  it('round-trips written settings', () => {
    writeSettings({ locale: 'en', motionMode: 'reduced', studentName: 'Alice', typingSpeedMs: 30 })
    expect(readSettings()).toEqual({
      locale: 'en',
      motionMode: 'reduced',
      studentName: 'Alice',
      typingSpeedMs: 30
    })
  })

  it('defaults typingSpeedMs to 50 when missing (backward compatible)', () => {
    localStorage.setItem('lex.settings', JSON.stringify({ locale: 'en' }))
    expect(readSettings().typingSpeedMs).toBe(50)
  })

  it('merges partial writes over previous value', () => {
    writeSettings({ locale: 'en' })
    writeSettings({ studentName: 'Bob' })
    expect(readSettings()).toEqual({
      ...DEFAULT_SETTINGS,
      locale: 'en',
      studentName: 'Bob'
    })
  })

  it('falls back to defaults on malformed JSON', () => {
    localStorage.setItem('lex.settings', '{not json')
    expect(readSettings()).toEqual(DEFAULT_SETTINGS)
  })
})

