import { mount } from '@vue/test-utils'
import { defineComponent } from 'vue'

/**
 * 在真正掛載的元件內執行一個 composable，讓 onMounted/onUnmounted 等生命週期鉤子
 * 能正常運作（跟 React 版 renderHook 的用途相同）。回傳 composable 結果與 unmount()。
 */
export function withSetup<T>(composable: () => T): { result: T; unmount: () => void } {
  let result!: T
  const wrapper = mount(
    defineComponent({
      setup() {
        result = composable()
        return () => null
      }
    })
  )
  return { result, unmount: () => wrapper.unmount() }
}

