import { describe, it, expect, beforeEach, vi } from 'vitest'
import { render, screen } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { defineComponent } from 'vue'
import MotionToggle from '@/components/stage/MotionToggle.vue'
import { provideSettings } from '@/composables/useSettings'
import { i18n } from '@/i18n'

function stubMatchMedia(matches = false) {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

const Host = defineComponent({
  components: { MotionToggle },
  setup() {
    provideSettings()
  },
  template: '<MotionToggle />'
})

describe('MotionToggle', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia(false)
  })

  it('reflects reduceMotion state and toggles motionMode on click', async () => {
    const user = userEvent.setup()
    render(Host, { global: { plugins: [i18n] } })
    // 測試環境 provideSettings 強制 motionMode='reduced' → reduceMotion=true → 動態關 → aria-checked=false
    const sw = screen.getByRole('switch')
    expect(sw.getAttribute('aria-checked')).toBe('false')
    await user.click(sw)
    // 切換後寫入 'full' → reduceMotion=false → 動態開 → aria-checked=true
    expect(sw.getAttribute('aria-checked')).toBe('true')
    expect(JSON.parse(localStorage.getItem('lex.settings')!).motionMode).toBe('full')
  })
})

