import '@testing-library/jest-dom/vitest'

// Node 22+ 內建了自己的 localStorage（需要 --localstorage-file 才能真正運作），這個測試環境下
// jsdom 建立 window 時也繼承了同一個壞掉的實例（globalThis.localStorage === window.localStorage，
// 兩者都缺方法），單純改指到 window.localStorage 沒有用。改用一份最小的記憶體版 Storage polyfill
// 蓋掉兩邊，讓 getItem/setItem/removeItem/clear 能正常運作。
class MemoryStorage implements Storage {
  private store = new Map<string, string>()
  get length() {
    return this.store.size
  }
  clear(): void {
    this.store.clear()
  }
  getItem(key: string): string | null {
    return this.store.has(key) ? this.store.get(key)! : null
  }
  key(index: number): string | null {
    return Array.from(this.store.keys())[index] ?? null
  }
  removeItem(key: string): void {
    this.store.delete(key)
  }
  setItem(key: string, value: string): void {
    this.store.set(key, String(value))
  }
}

const memoryStorage = new MemoryStorage()
for (const target of [globalThis, window]) {
  Object.defineProperty(target, 'localStorage', {
    configurable: true,
    value: memoryStorage
  })
}

