1	using chatai.Core.Config;
2	using chatai.Core.Service;
3	using chatai_backend.Attribute;
4	using chatai_backend.Controllers.Base;
5	using chatai_backend.Helpers;
6	using chatai_backend.Model;
7	using Microsoft.AspNetCore.Mvc;
8	using ntu.Common.Utility.Helper;
9	using System.Net.Http.Headers;
10	using System.Text;
11	using System.Text.Json;
12	
13	namespace chatai_backend.Controllers
14	{
15	    [Route("api/run")]
16	    [NeedSignature]
17	    public class RunController : BaseApiController
18	    {
19	        /// <summary>
20	        /// flowId=6 走 Gemini File Search RAG，不再 proxy 到 Langflow
21	        /// </summary>
22	        private const int GeminiFlowIndex = 6;
23	
24	        /// <summary>
25	        /// flowId=7：學習規劃探索助手，直接呼叫 Gemini（不用 file_search），不再 proxy 到 Langflow
26	        /// </summary>
27	        private const int AdvisingFlowIndex = 7;
28	
29	        /// <summary>
30	        /// flowId=8：未來教室設備支援助理，直接呼叫 Gemini（不用 file_search），不再 proxy 到 Langflow
31	        /// </summary>
32	        private const int ClassroomFaqFlowIndex = 8;
33	
34	        private readonly IHttpClientFactory _httpClientFactory;
35	        private readonly AppSettingConfig _appSetting;
36	        private readonly SignatureContext _signatureContext;
37	        private readonly IGeminiFileSearchService _geminiService;
38	        private readonly IAdvisingChatService _advisingService;
39	        private readonly IClassroomFaqChatService _classroomFaqService;
40	        private readonly ILogger<RunController> _logger;
41	
42	        public RunController(
43	            IHttpClientFactory httpClientFactory,
44	            AppSettingConfig appSetting,
45	            SignatureContext signatureContext,
46	            IGeminiFileSearchService geminiService,
47	            IAdvisingChatService advisingService,
48	            IClassroomFaqChatService classroomFaqService,
49	            ILogger<RunController> logger)
50	        {
51	            _httpClientFactory = httpClientFactory;
52	            _appSetting = appSetting;
53	            _signatureContext = signatureContext;
54	            _geminiService = geminiService;
55	            _advisingService = advisingService;
56	            _classroomFaqService = classroomFaqService;
57	            _logger = logger;
58	        }
59	
60	        [HttpGet]
61	        public IActionResult Get()
62	        {
63	            return Content("");
64	        }
65	
66	        [HttpPost]
67	        public async Task<IActionResult> Post([FromBody] JsonElement body)
68	        {
69	            var apiFlowIndex = _signatureContext.apiFlow;
70	
71	            if (apiFlowIndex == GeminiFlowIndex)
72	                return await RunGeminiFlow(body);
73	
74	            if (apiFlowIndex == AdvisingFlowIndex)
75	                return await RunAdvisingFlow(body);
76	
77	            if (apiFlowIndex == ClassroomFaqFlowIndex)
78	                return await RunClassroomFaqFlow(body);
79	
80	            var apiUrl = _appSetting.ApiUrl;
81	            var apiKey = _appSetting.ApiKey;
82	            var flowIds = _appSetting.FlowIds;
83	
84	            if (string.IsNullOrEmpty(apiUrl)
85	                || string.IsNullOrEmpty(apiKey)
86	                || flowIds == null
87	                || !flowIds.Any())
88	                throw new Exception("Missing configuration values.");
89	
90	            //var stream = HttpContext.Request.Query["stream"].ToNullString().ToBoolean().ToString().ToLower();
91	
92	            if (flowIds.Count() <= apiFlowIndex)
93	                return BadRequest("Invalid API flow index.");
94	
95	            var flowId = flowIds.Skip(apiFlowIndex).First();
96	
97	            var targetUrl = $"{apiUrl}/api/v1/run/{flowId}";//?stream={stream}
98	
99	            using var client = _httpClientFactory.CreateClient("NoSsl");
100	            var json = body.GetRawText();
101	            var jsonBytes = Encoding.UTF8.GetBytes(json);
102	            using var content = new ByteArrayContent(jsonBytes)
103	            {
104	                Headers =
105	                {
106	                    ContentType = new MediaTypeHeaderValue("application/json"),
107	                    ContentLength = jsonBytes.Length
108	                }
109	            };
110	
111	            var requestMessage = new HttpRequestMessage(HttpMethod.Post, targetUrl)
112	            {
113	                Content = content
114	            };
115	
116	            requestMessage.Content?.Headers.TryAddWithoutValidation("x-api-key", apiKey);
117	
118	            var response = await client.SendAsync(requestMessage, HttpCompletionOption.ResponseHeadersRead);
119	            var responseBody = await response.Content.ReadAsStringAsync();
120	
121	            Response.Headers.Append("x-flow", $"{apiFlowIndex}");
122	
123	            return Content(responseBody, response.Content.Headers.ContentType?.ToString() ?? "application/json");
124	        }
125	
126	        /// <summary>
127	        /// flowId=6：改用 Gemini File Search 做 RAG，以 SSE 串流方式即時把答案文字吐給前端，
128	        /// 每個 event 是一行 `data: {...}\n\n`，格式為 { delta, source, done, error }。
129	        /// </summary>
130	        private async Task<IActionResult> RunGeminiFlow(JsonElement body)
131	        {
132	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
133	            if (string.IsNullOrEmpty(userId))
134	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
135	
136	            if (!body.TryGetProperty("input_value", out var inputValueEl))
137	                return BadRequest("Missing input_value.");
138	
139	            var inputValue = inputValueEl.GetString() ?? "";
140	
141	            Response.ContentType = "text/event-stream";
142	            Response.Headers.Append("Cache-Control", "no-cache");
143	            Response.Headers.Append("x-flow", $"{GeminiFlowIndex}");
144	
145	            await foreach (var chunk in _geminiService.QueryStreamAsync(inputValue, userId))
146	            {
147	                var payload = JsonSerializer.Serialize(new
148	                {
149	                    delta = chunk.Delta,
150	                    source = chunk.Source,
151	                    done = chunk.Done,
152	                    error = chunk.Error,
153	                });
154	                await Response.WriteAsync($"data: {payload}\n\n");
155	                await Response.Body.FlushAsync();
156	            }
157	
158	            return new EmptyResult();
159	        }
160	
161	        /// <summary>
162	        /// flowId=7：學習規劃探索助手，直接呼叫 Gemini 做多輪對話，以 SSE 串流方式即時把答案文字吐給前端。
163	        /// 後端沒有 session 儲存機制，多輪對話紀錄由前端透過 body.history 每次完整帶入。
164	        /// </summary>
165	        private async Task<IActionResult> RunAdvisingFlow(JsonElement body)
166	        {
167	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
168	            if (string.IsNullOrEmpty(userId))
169	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
170	
171	            if (!body.TryGetProperty("input_value", out var inputValueEl))
172	                return BadRequest("Missing input_value.");
173	
174	            var inputValue = inputValueEl.GetString() ?? "";
175	
176	            var history = new List<(string Role, string Text)>();
177	            if (body.TryGetProperty("history", out var historyEl) && historyEl.ValueKind == JsonValueKind.Array)
178	            {
179	                foreach (var item in historyEl.EnumerateArray())
180	                {
181	                    var role = item.TryGetProperty("role", out var roleEl) ? roleEl.GetString() : null;
182	                    var text = item.TryGetProperty("text", out var textEl) ? textEl.GetString() : null;
183	                    if (string.IsNullOrEmpty(role) || string.IsNullOrEmpty(text))
184	                        continue;
185	                    history.Add((role, text));
186	                }
187	            }
188	
189	            // 前端透過 ?model= 帶入（例如 /?flow=7&model=claude），對應 body.model；未帶則預設 gemini
190	            var model = "gemini";
191	            if (body.TryGetProperty("model", out var modelEl) && modelEl.ValueKind == JsonValueKind.String)
192	            {
