1	import * as forge from "node-forge";
2	import { type Ref } from "vue";
3	import { MessageStatus as Status } from "@/lib/type";
4	import { Role } from "@/lib/enum";
5	import { getApiUrl } from "@/lib/utils";
6	import type { Message } from "@/lib/type";
7	
8	export type CallConfig = {
9	  content: string;
10	  flowId: string;
11	  loadingText?: string;
12	  history?: { role: "user" | "model"; text: string }[];
13	  image?: { mimeType: string; data: string };
14	  /** flow=7（學習規劃探索助手）用：切換底層呼叫的 AI 供應商，例如 "gemini"（預設）、"openai"、"claude" */
15	  model?: string;
16	};
17	
18	export class QuotaExceededError extends Error {
19	  constructor(message: string) {
20	    super(message);
21	    this.name = "QuotaExceededError";
22	  }
23	}
24	
25	export interface AICallContext {
26	  messages: Ref<Message[][]>;
27	  publicKey: string;
28	  fingerprint: Ref<string> | undefined;
29	  jwtToken: Ref<string>;
30	  route: { query: { flow?: string | string[] } };
31	}
32	
33	/**
34	 * 加密簽名
35	 */
36	export async function encryptSignature(
37	  publicKeyBase64: string,
38	  text: string,
39	): Promise<string> {
40	  const publicKeyPem = `-----BEGIN PUBLIC KEY-----\n${publicKeyBase64}\n-----END PUBLIC KEY-----`;
41	  const publicKey = forge.pki.publicKeyFromPem(publicKeyPem);
42	
43	  const encryptedBytes = publicKey.encrypt(text, "RSA-OAEP", {
44	    md: forge.md.sha256.create(),
45	  });
46	
47	  return forge.util.encode64(encryptedBytes);
48	}
49	
50	/**
51	 * 顯示錯誤訊息
52	 */
53	function showErrorMessage(
54	  messages: Ref<Message[][]>,
55	  mIdx: number,
56	  idx: number,
57	) {
58	  messages.value[mIdx][idx] = {
59	    role: Role.Assistant,
60	    content: `beta 測試版發生錯誤，懇請重新登入或撥冗使用 QR code 進行回報`,
61	    timestamp: Date.now(),
62	    status: Status.Error,
63	  };
64	}
65	
66	/**
67	 * 執行 AI 調用（包含簽名生成）
68	 */
69	async function executeAICall(
70	  context: AICallContext,
71	  mIdx: number,
72	  idx: number,
73	  config: CallConfig,
74	): Promise<void> {
75	  const timestamp = Date.now();
76	  const signature = await encryptSignature(
77	    context.publicKey,
78	    `${context.fingerprint?.value} ${timestamp} ${config.flowId}`,
79	  );
80	
81	  // flowId=6（Gemini File Search RAG）、flowId=7（學習規劃探索助手）、
82	  // flowId=8（未來教室設備支援助理）走串流，其他 flow 維持非串流
83	  if (config.flowId === "6" || config.flowId === "7" || config.flowId === "8") {
84	    await callStream(context, mIdx, idx, config, signature);
85	  } else {
86	    await callNonStream(context, mIdx, idx, config, signature);
87	  }
88	}
89	
90	/**
91	 * 非流式 AI 調用
92	 */
93	async function callNonStream(
94	  context: AICallContext,
95	  mIdx: number,
96	  idx: number,
97	  config: CallConfig,
98	  signature: string,
99	) {
100	  context.messages.value[mIdx][idx] = {
101	    role: Role.Assistant,
102	    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
103	    timestamp: Date.now(),
104	    status: Status.Pending,
105	  };
106	
107	  const res = await fetch(getApiUrl("/api/run?stream=false"), {
108	    method: "POST",
109	    headers: {
110	      "Content-Type": "application/json",
111	      Authorization: signature,
112	      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
113	    },
114	    body: JSON.stringify({ input_value: config.content }),
115	  });
116	
117	  if (!res.ok) {
118	    const errorText = await res.text();
119	    // 檢查是否是額度用光的錯誤
120	    if (
121	      res.status === 429 ||
122	      errorText.includes("quota") ||
123	      errorText.includes("額度") ||
124	      errorText.includes("limit") ||
125	      errorText.includes("exceeded")
126	    ) {
127	      throw new QuotaExceededError(errorText);
128	    }
129	    throw new Error(errorText);
130	  }
131	
132	  const data = await res.json();
133	
134	  if (data.detail) {
135	    // 檢查 detail 中是否包含額度相關錯誤
136	    const detailStr = String(data.detail);
137	    if (
138	      detailStr.includes("quota") ||
139	      detailStr.includes("額度") ||
140	      detailStr.includes("limit") ||
141	      detailStr.includes("exceeded")
142	    ) {
143	      throw new QuotaExceededError(detailStr);
144	    }
145	    throw new Error(detailStr);
146	  }
147	
148	  data.outputs?.[0].outputs.forEach((output: any, i: number) => {
149	    context.messages.value[mIdx][idx + i] = {
150	      role: Role.Assistant,
151	      content: output.artifacts.message,
152	      timestamp: Date.now(),
153	      status: Status.End,
154	      source: config.flowId === "5"
155	        ? output.results.message.data.properties.source.source
156	        : "",
157	    };
158	  });
159	}
160	
161	type SseStreamPayload = {
162	  delta?: string;
163	  source?: string;
164	  done?: boolean;
165	  error?: string;
166	};
167	
168	function isQuotaErrorText(status: number, text: string): boolean {
169	  return (
170	    status === 429 ||
171	    text.includes("quota") ||
172	    text.includes("額度") ||
173	    text.includes("limit") ||
174	    text.includes("exceeded")
175	  );
176	}
177	
178	/** 把一行文字解析成 SSE payload；不是 `data: ` 開頭的行（例如空白分隔行）回傳 null */
179	function parseSseLine(rawLine: string): SseStreamPayload | null {
180	  const line = rawLine.trim();
181	  if (!line.startsWith("data: ")) return null;
182	  return JSON.parse(line.slice("data: ".length));
183	}
184	
185	/** 讀取一個 SSE response body，逐段解析出 payload 陣列（可能因為 chunk 邊界而一次拿到多個或零個） */
186	async function readSseChunk(
187	  reader: ReadableStreamDefaultReader<Uint8Array>,
188	  decoder: TextDecoder,
189	  bufferRef: { value: string },
190	): Promise<{ done: boolean; payloads: SseStreamPayload[] }> {
191	  const { done, value } = await reader.read();
192	  if (done) return { done: true, payloads: [] };
193	
194	  bufferRef.value += decoder.decode(value, { stream: true });
195	  const events = bufferRef.value.split("\n\n");
196	  bufferRef.value = events.pop() ?? ""; // 最後一段可能還不完整，留到下一輪繼續接
197	
198	  const payloads = events
199	    .map(parseSseLine)
200	    .filter((p): p is SseStreamPayload => p !== null);
201	  return { done: false, payloads };
202	}
203	
204	type StreamAccumulator = {
205	  content: string;
206	  source: string;
207	  hasReceivedContent: boolean;
208	};
209	
210	/** 套用單一 SSE payload 到累積狀態，並即時更新畫面上的訊息內容 */
211	function applyStreamPayload(
212	  payload: SseStreamPayload,
213	  acc: StreamAccumulator,
214	  context: AICallContext,
215	  mIdx: number,
216	  idx: number,
217	) {
218	  if (payload.error) throw new Error(payload.error);
219	
220	  if (payload.delta) {
221	    acc.content += payload.delta;
222	    acc.hasReceivedContent = true;
223	    context.messages.value[mIdx][idx] = {
224	      role: Role.Assistant,
225	      content: acc.content,
226	      timestamp: Date.now(),
227	      status: Status.Receiving,
228	    };
229	  }
230	
231	  if (payload.done) acc.source = payload.source ?? "";
232	}
233	
234	/** 讀完整個 SSE response body，過程中即時更新畫面，回傳最終累積狀態 */
235	async function consumeSseStream(
236	  res: Response,
237	  context: AICallContext,
238	  mIdx: number,
239	  idx: number,
240	): Promise<StreamAccumulator> {
241	  const reader = res.body!.getReader();
242	  const decoder = new TextDecoder("utf-8");
243	  const bufferRef = { value: "" };
244	  const acc: StreamAccumulator = { content: "", source: "", hasReceivedContent: false };
245	
