import type { FastAssessment, RecommendedResource, SummarySection } from '@/types'

/**
 * 把 AdvisingChatService 回覆的自由文字解析成畫面要的結構化資料。
 * 這裡用到的標記文字（【】、📊、🎓…）都逐字對應 AdvisingChatService.cs 的 system prompt
 * 模板，模板一旦改了措辭這裡也要跟著改。所有解析函式失敗時一律回傳 null／略過該欄位，
 * 呼叫端要自己接住並退回顯示 rawReply，不能假設一定解析得出來。
 */

export interface Stage2Parsed {
  questionNumber: number
  reflection: string
  question: string
}

const STAGE2_PATTERN = /（第\s*(\d+)\s*\/\s*10\s*題）\s*\n+([\s\S]*?)\n{2,}([\s\S]*)/

/** Stage 2：拆「（第 X / 10 題）」「反映」「提問」三段；格式對不上就回傳 null。 */
export function parseStage2Reply(text: string): Stage2Parsed | null {
  const match = text.match(STAGE2_PATTERN)
  if (!match) return null
  const [, numberText, reflection, question] = match
  const questionNumber = Number(numberText)
  if (!Number.isFinite(questionNumber) || questionNumber < 1 || questionNumber > 10) return null
  const trimmedReflection = reflection.trim()
  const trimmedQuestion = question.trim()
  if (!trimmedQuestion) return null
  return { questionNumber, reflection: trimmedReflection, question: trimmedQuestion }
}

/** Stage 1.5 六句自評問句的第一句是固定文字，用它判斷「這輪進入 FAST 自評」。 */
export function isFastAssessmentPrompt(text: string): boolean {
  return text.includes('我知道自己的學習興趣')
}

const REPORT_MARKER = '📋 你的學習規劃報告'

/** Stage 3 總結報告的固定開頭標題，用它判斷「這輪是最終報告」。 */
export function isFinalReport(text: string): boolean {
  return text.includes(REPORT_MARKER)
}

const SECTION_MARKERS = {
  issue: '【你想談的議題】',
  status: '【目前的狀況】',
  strengths: '【你的優勢與資源】',
  directions: '【可能的探索方向】',
  fastBlock: '📊 你的 FAST Model 學習狀態',
  advice: '【探索建議】',
  resources: '🎓 推薦臺大學習資源'
} as const

const SECTION_ORDER = Object.values(SECTION_MARKERS)

const SECTION_TITLES: Record<'issue' | 'status' | 'strengths' | 'directions' | 'resources', string> = {
  issue: '你想談的議題',
  status: '目前的狀況',
  strengths: '你的優勢與資源',
  directions: '可能的探索方向',
  resources: '推薦臺大學習資源'
}

function nextMarkersAfter(marker: string): string[] {
  const idx = SECTION_ORDER.indexOf(marker as (typeof SECTION_ORDER)[number])
  return idx >= 0 ? SECTION_ORDER.slice(idx + 1) : []
}

function extractBetween(text: string, startMarker: string, endMarkers: string[]): string | null {
  const startIdx = text.indexOf(startMarker)
  if (startIdx < 0) return null
  const from = startIdx + startMarker.length
  let endIdx = text.length
  for (const marker of endMarkers) {
    const idx = text.indexOf(marker, from)
    if (idx >= 0 && idx < endIdx) endIdx = idx
  }
  const body = text.slice(from, endIdx).trim()
  return body || null
}

function toItems(body: string): string[] | undefined {
  const lines = body
    .split('\n')
    .map(line => line.replace(/^[-•]\s*/, '').trim())
    .filter(Boolean)
  return lines.length > 1 ? lines : undefined
}

const RESOURCE_ENTRY_PATTERN =
  /\d+\.\s*【([^】]+)】\s*\n📌[^\n]*\n🔗\s*連結：([^\n]+)\n💡\s*推薦原因：([^\n]+)/g

function parseResources(body: string): RecommendedResource[] {
  const resources: RecommendedResource[] = []
  for (const match of body.matchAll(RESOURCE_ENTRY_PATTERN)) {
    const [, name, url, reason] = match
    resources.push({ name: name.trim(), type: '', url: url.trim(), reason: reason.trim() })
  }
  return resources
}

const QUADRANT_MAP: Record<string, 1 | 2 | 3 | 4> = { 第一: 1, 第二: 2, 第三: 3, 第四: 4 }

export interface Stage3Parsed {
  summary: SummarySection[]
  fast?: Pick<FastAssessment, 'directionScore' | 'resourceScore' | 'quadrant' | 'advice'>
}

/** Stage 3：依固定 marker 切出五個報告段落 + FAST 象限分數／建議文字。整段解析不出來就回傳 null。 */
export function parseStage3Report(text: string): Stage3Parsed | null {
  if (!isFinalReport(text)) return null

  const summary: SummarySection[] = []
  for (const key of ['issue', 'status', 'strengths', 'directions'] as const) {
    const marker = SECTION_MARKERS[key]
    const body = extractBetween(text, marker, nextMarkersAfter(marker))
    if (!body) continue
    const items = toItems(body)
    summary.push({ key, title: SECTION_TITLES[key], body, ...(items ? { items } : {}) })
  }

  const resourceBody = extractBetween(text, SECTION_MARKERS.resources, [])
  if (resourceBody) {
    const resources = parseResources(resourceBody)
    summary.push({
      key: 'resources',
      title: SECTION_TITLES.resources,
      body: resourceBody,
      ...(resources.length ? { resources } : {})
    })
  }

  if (summary.length === 0) {
    // 一個段落都切不出來，回傳原始全文當單一段落，至少畫面不會開天窗
    return { summary: [{ key: 'raw', title: '總結報告', body: text }] }
  }

  let fast: Stage3Parsed['fast']
  const fastBody = extractBetween(text, SECTION_MARKERS.fastBlock, nextMarkersAfter(SECTION_MARKERS.fastBlock))
  const adviceBody = extractBetween(text, SECTION_MARKERS.advice, nextMarkersAfter(SECTION_MARKERS.advice))
  if (fastBody) {
    const directionMatch = fastBody.match(/學習方向明確度[：:]\s*([\d.]+)/)
    const resourceMatch = fastBody.match(/學習資源掌握度[：:]\s*([\d.]+)/)
    const quadrantMatch = fastBody.match(/你的落點[：:]\s*(第[一二三四])象限/)
    if (directionMatch && resourceMatch && quadrantMatch) {
      fast = {
        directionScore: Number(directionMatch[1]),
        resourceScore: Number(resourceMatch[1]),
        quadrant: QUADRANT_MAP[quadrantMatch[1]],
        advice: adviceBody ?? undefined
      }
    }
  }

  return { summary, fast }
}

