const RESOURCE_ENTRY_PATTERN =
  /\d+\.\s*【([^】]+)】\s*\n📌[^\n]*\n🔗\s*連結：([^\n]+)\n💡\s*推薦原因：([^\n]+)/g

function parseResources(body: string): RecommendedResource[] {
  const resources: RecommendedResource[] = []
  for (const match of body.matchAll(RESOURCE_ENTRY_PATTERN)) {
    const [, name, url, reason] = match
    resources.push({ name: name.trim(), type: '', url: url.trim(), reason: reason.trim() })
  }
  return resources
}

const QUADRANT_MAP: Record<string, 1 | 2 | 3 | 4> = { 第一: 1, 第二: 2, 第三: 3, 第四: 4 }

export interface Stage3Parsed {
  summary: SummarySection[]
  fast?: Pick<FastAssessment, 'directionScore' | 'resourceScore' | 'quadrant' | 'advice'>
}

/** Stage 3：依固定 marker 切出五個報告段落 + FAST 象限分數／建議文字。整段解析不出來就回傳 null。 */
export function parseStage3Report(text: string): Stage3Parsed | null {
  if (!isFinalReport(text)) return null

  const summary: SummarySection[] = []
  for (const key of ['issue', 'status', 'strengths', 'directions'] as const) {
    const marker = SECTION_MARKERS[key]
    const body = extractBetween(text, marker, nextMarkersAfter(marker))
    if (!body) continue
    const items = toItems(body)
    summary.push({ key, title: SECTION_TITLES[key], body, ...(items ? { items } : {}) })
  }

  const resourceBody = extractBetween(text, SECTION_MARKERS.resources, [])
  if (resourceBody) {
    const resources = parseResources(resourceBody)
    summary.push({
      key: 'resources',
      title: SECTION_TITLES.resources,
      body: resourceBody,
      ...(resources.length ? { resources } : {})
    })
  }

  if (summary.length === 0) {
    // 一個段落都切不出來，回傳原始全文當單一段落，至少畫面不會開天窗
    return { summary: [{ key: 'raw', title: '總結報告', body: text }] }
  }

  let fast: Stage3Parsed['fast']
  const fastBody = extractBetween(text, SECTION_MARKERS.fastBlock, nextMarkersAfter(SECTION_MARKERS.fastBlock))
  const adviceBody = extractBetween(text, SECTION_MARKERS.advice, nextMarkersAfter(SECTION_MARKERS.advice))
  if (fastBody) {
    const directionMatch = fastBody.match(/學習方向明確度[：:]\s*([\d.]+)/)
    const resourceMatch = fastBody.match(/學習資源掌握度[：:]\s*([\d.]+)/)
    const quadrantMatch = fastBody.match(/你的落點[：:]\s*(第[一二三四])象限/)
    if (directionMatch && resourceMatch && quadrantMatch) {
      fast = {
        directionScore: Number(directionMatch[1]),
        resourceScore: Number(resourceMatch[1]),
        quadrant: QUADRANT_MAP[quadrantMatch[1]],
        advice: adviceBody ?? undefined
      }
    }
  }

  return { summary, fast }
}

