 * 命名一律英文；註解說明設計意圖。
 */
:root {
  /* ── 基底與面板 ── */
  --color-bg-base: #080b11;
  --color-panel: rgba(18, 22, 30, 0.97);
  --color-panel-solid: rgba(18, 22, 30, 0.98);
  --color-panel-menu: rgba(14, 18, 26, 0.94);
  --color-panel-chip: rgba(16, 20, 28, 0.72);
  --color-panel-chip-hover: rgba(30, 36, 46, 0.92);
  --color-scrim: rgba(4, 6, 10, 0.74);

  /* ── 文字階層（白色不同透明度，對應設計稿逐一取值）── */
  --color-fg-primary: rgba(255, 255, 255, 0.95);
  --color-fg-strong: rgba(255, 255, 255, 0.92);
  --color-fg-body: rgba(255, 255, 255, 0.85);
  --color-fg-answer: rgba(255, 255, 255, 0.9);
  --color-fg-muted: rgba(255, 255, 255, 0.62);
  --color-fg-subtle: rgba(255, 255, 255, 0.5);
  --color-fg-faint: rgba(255, 255, 255, 0.45);
  --color-fg-hushed: rgba(255, 255, 255, 0.4);
  --color-fg-whisper: rgba(255, 255, 255, 0.36);
  --color-fg-ghost: rgba(255, 255, 255, 0.28);
  --color-fg-dormant: rgba(255, 255, 255, 0.24);
  --color-fg-dim: rgba(255, 255, 255, 0.14);

  /* ── 光：強調色 ── */
  --color-accent: #e6c9a0;
  --color-accent-bright: #f3ddba;
  --color-accent-ink: #1a1206;
  --gradient-accent: linear-gradient(135deg, #f2ead9, rgba(230, 201, 160, 0.82));
  --color-accent-border: rgba(230, 201, 160, 0.35);
  --color-accent-focus: rgba(230, 201, 160, 0.5);
  --color-accent-wash: rgba(230, 201, 160, 0.12);
  --color-danger: rgba(224, 120, 110, 0.9);

  /* ── 品牌色（NTU 教務處 #BB937A 系）：套用於按鈕與關鍵強調，不覆蓋上方奶油金 accent ── */
  --color-brand: #bb937a;
  --color-brand-cream: #faedcd;
  --gradient-brand: linear-gradient(108deg, #faedcd -19.5%, #bb937a 56.94%);
  --color-brand-focus: rgba(187, 147, 122, 0.5);
  --color-brand-border: rgba(187, 147, 122, 0.4);

  /* ── 半透明面與邊 ── */
  --surface-1: rgba(255, 255, 255, 0.03);
  --surface-2: rgba(255, 255, 255, 0.035);
  --surface-3: rgba(255, 255, 255, 0.05);
  --surface-hover: rgba(255, 255, 255, 0.09);
  --surface-hover-strong: rgba(255, 255, 255, 0.12);
  --border-hairline: rgba(255, 255, 255, 0.08);
  --border-subtle: rgba(255, 255, 255, 0.1);
  --border-default: rgba(255, 255, 255, 0.14);
  --border-medium: rgba(255, 255, 255, 0.18);
  --border-strong: rgba(255, 255, 255, 0.26);
  --border-bright: rgba(255, 255, 255, 0.35);

  /* ── 字體 ── */
  --font-serif: 'Noto Serif TC', 'PingFang TC', 'Microsoft JhengHei', Georgia, serif;
  --font-sans: 'Noto Sans TC', 'PingFang TC', 'Microsoft JhengHei', -apple-system,
    BlinkMacSystemFont, sans-serif;
  --font-mono: ui-monospace, Menlo, Consolas, monospace;

  /* 字級（設計稿為 px 直接取值，保留原值以求視覺一致） */
  --fs-eyebrow: 12.5px;
  --fs-caption: 13px;
  --fs-body-sm: 13.5px;
  --fs-body: 14.5px;
  --fs-body-lg: 15.5px;
  --fs-answer: 17px;
  --fs-title-sm: 19px;
  --fs-title: 25px;
  --fs-title-lg: 27px;
  --fs-display: 31px;
  --fs-counter: 42px;

  --tracking-eyebrow: 0.34em;
  --tracking-label: 0.26em;
  --tracking-wide: 0.14em;
  --tracking-button: 0.06em;

  /* ── 圓角 ── */
  --radius-pill: 999px;
  --radius-card: 22px;
  --radius-dialog: 20px;
  --radius-panel: 16px;
  --radius-field: 14px;
  --radius-chip: 12px;
  --radius-input: 10px;
  --radius-menu-item: 9px;
  --radius-check: 6px;

  /* ── 動效 ── */
  --motion-quick: 0.2s;
  --motion-base: 0.3s;
  --motion-soft: 0.35s;
  --motion-reveal: 0.55s;
  --motion-scene: 0.9s;
  --motion-tone: 2.8s;
  --motion-backdrop: 3.4s;
  --easing-soft: cubic-bezier(0.2, 0.8, 0.3, 1);
  --easing-spark: cubic-bezier(0.2, 0.7, 0.3, 1);

  /* ── 版面 ── */
  --content-narrow: 520px;
  --content-form: 560px;
  --content-read: 620px;
  --content-wide: 680px;
  --content-question: 720px;
  --content-topics: 780px;
  --content-reflection: 780px;

  /* ── 沉浸舞台：由 StageContext 於執行期覆寫 ── */
  --stage-glow-a: #1f4d73;
  --stage-glow-b: #155e63;
  --stage-glow-a-x: 22%;
  --stage-glow-a-y: 20%;
  --stage-glow-b-x: 82%;
  --stage-glow-b-y: 78%;
  --stage-glow-opacity: 0.46;
  --stage-progress: 2%;

  --color-focus-ring: rgba(187, 147, 122, 0.65); /* 品牌色 #BB937A：關鍵互動 focus 外框 */
}

/** Stage 3：依固定 marker 切出五個報告段落 + FAST 象限分數／建議文字。整段解析不出來就回傳 null。 */
export function parseStage3Report(text: string): Stage3Parsed | null {
  if (!isFinalReport(text)) return null

  const summary: SummarySection[] = []
  for (const key of ['issue', 'status', 'strengths', 'directions'] as const) {
    const marker = SECTION_MARKERS[key]
    const body = extractBetween(text, marker, nextMarkersAfter(marker))
    if (!body) continue
    const items = toItems(body)
    summary.push({ key, title: SECTION_TITLES[key], body, ...(items ? { items } : {}) })
  }

  const resourceBody = extractBetween(text, SECTION_MARKERS.resources, [])
  if (resourceBody) {
    const resources = parseResources(resourceBody)
