import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen, waitFor } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { renderApp } from '../helpers/renderApp'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

/**
 * 一律透過 i18n key 取文字，而非寫死中文字面值，
 * 這樣調整文案時不會連帶弄壞這支測試。
 */
const label = (key: string) => i18n.global.t(key)

describe('happy path', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it(
    'user can consent, enter the ritual, pick a topic, answer 10 questions, and reach the card',
    async () => {
      const user = userEvent.setup()
      await renderApp('/consent')

      // ── 條款同意 ────────────────────────────────────────────────
      const checkbox = await screen.findByRole('checkbox')
      await user.click(checkbox)
      await user.click(screen.getByRole('button', { name: label('consent.next') }))

      // ── 入口儀式 ────────────────────────────────────────────────
      await user.click(await screen.findByRole('button', { name: label('ritual.continue') }))

      // ── 首頁 ────────────────────────────────────────────────────
      await user.click(await screen.findByRole('button', { name: label('home.startExploring') }))

      // ── 議題選擇：點卡片即開始 ──────────────────────────────────
      const topicCards = await screen.findAllByRole('button', {
        name: new RegExp(label('topics.career'))
      })
      await user.click(topicCards[0])

      // ── 一題一幕探索：反映段 → 提問段 → 作答 ────────────────────
      for (let index = 0; index < 10; index += 1) {
        // 減弱動效下揭字立即完成，點擊反映段即進入提問
        await user.click(await screen.findByText(label('exploration.continueHint')))

        const textbox = await screen.findByRole('textbox', { name: label('exploration.inputLabel') })
        await user.clear(textbox)
        await user.type(textbox, `answer ${index}`)

        const submitKey = index === 9 ? 'exploration.finish' : 'exploration.next'
        await user.click(screen.getByRole('button', { name: label(submitKey) }))
      }

      // ── 沉澱過場（減弱動效 → 600 ms 自動導向）→ 總結 ────────────
      await waitFor(() => expect(screen.getByText(label('summary.eyebrow'))).toBeInTheDocument(), {
        timeout: 8000
      })

      await user.click(
        await screen.findByRole('button', { name: label('summary.continue') }, { timeout: 8000 })
      )

      // ── 凝聚成卡過場 → 自我察覺卡 ───────────────────────────────
      await waitFor(
        () => expect(screen.getByRole('button', { name: label('card.bookAppointment') })).toBeInTheDocument(),
        { timeout: 12000 }
      )
      expect(screen.getAllByRole('img', { name: label('card.title') }).length).toBeGreaterThan(0)
    },
    40000
  )
})

