import { screen, waitFor, within } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { renderApp } from '../helpers/renderApp'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

/**
 * 一律透過 i18n key 取文字，而非寫死中文字面值，
 * 這樣調整文案時不會連帶弄壞這支測試。
 */
const label = (key: string) => i18n.global.t(key)

/**
 * Mock AdvisingChatService 的階段式回覆（見 AdvisingChatService.cs），格式要跟
 * src/services/advisingParser.ts 的解析規則對得上，這支測試才能走完真實流程的 UI/解析邏輯，
 * 而不必真的打網路。history 陣列長度決定目前是哪一輪，推算方式見 useAdvisingConversation.ts
 * 的呼叫序列：0=開場、2=FAST 提示、4~22=第 1~10 題、24 之後=總結報告。
 */
vi.mock('@/services/advisingApi', () => ({
  sendAdvisingMessage: vi.fn(
    async (
      _content: string,
      history: { role: string; text: string }[],
      onDelta?: (delta: string, accumulated: string) => void
    ) => {
      const len = history.length
      let reply: string
      if (len === 0) {
        reply = '你好，我是臺大學習規劃辦公室的 AI 學習探索助手。你最近想和學習規劃師聊什麼學習議題呢？'
      } else if (len === 2) {
        reply = [
          '請針對以下六句評估你目前的狀況：',
