import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { seedDemoExploration } from '@/data/demo-seed'
import { getExploration } from '@/storage/explorations'
import { renderApp } from '../helpers/renderApp'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((q: string) => ({
      matches: false,
      media: q,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

describe('node jump', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it('jumps to an earlier answered question and truncates later answers', async () => {
    const user = userEvent.setup()
    const exp = seedDemoExploration('answered') // 10 題皆已作答
    await renderApp(`/explore/${exp.id}?q=10`) // currentIndex=9, question 階段

    const buttons = await screen.findAllByRole('button', { name: /第 \d+ 題/ })
    await user.click(buttons[2]) // 第 3 題（index 2，已答且早於 current）

    await user.click(await screen.findByRole('button', { name: i18n.global.t('exploration.reviseConfirm') }))

    expect(await screen.findByText('03')).toBeInTheDocument()
    await new Promise(r => setTimeout(r, 350))
    const after = getExploration(exp.id)!
    expect(after.answers.map(a => a.questionIndex).sort((x, y) => x - y)).toEqual([0, 1, 2])
  })
})

