async function handleAudioTranscriptionWrapper(audioBlob: Blob) {
  const context: AudioTranscriptionContext = {
    publicKey,
    fingerprint,
    jwtToken,
    isTranscribing,
  };
  return handleAudioTranscription(context, audioBlob);
}

/**
 * 上傳文件到 flowId=6 的個人知識庫，上傳狀態透過聊天訊息呈現
 */
async function handleFileUploadWrapper(file: File) {
  const messageIndex = addUserMessage(`📎 上傳文件：${file.name}`);
