    listen 80;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

	# 增加 Request Header Buffer
    client_header_buffer_size 8k;
    large_client_header_buffers 4 16k;

    # flow=7（學習規劃探索助手）的獨立部署，跟主站同源、不同 base path；
    # client-side 路由（例如 /explore/consent）重新整理時要 fallback 回它自己的 index.html，
