file.content:
import type { FastAssessment, RecommendedResource, SummarySection } from '@/types'

/**
 * 把 AdvisingChatService 回覆的自由文字解析成畫面要的結構化資料。
 * 這裡用到的標記文字（【】、📊、🎓…）都逐字對應 AdvisingChatService.cs 的 system prompt
 * 模板，模板一旦改了措辭這裡也要跟著改。所有解析函式失敗時一律回傳 null／略過該欄位，
 * 呼叫端要自己接住並退回顯示 rawReply，不能假設一定解析得出來。
 */

export interface Stage2Parsed {
  questionNumber: number
  reflection: string
  question: string
}

const STAGE2_PATTERN = /（第\s*(\d+)\s*\/\s*10\s*題）\s*\n+([\s\S]*?)\n{2,}([\s\S]*)/

/** Stage 2：拆「（第 X / 10 題）」「反映」「提問」三段；格式對不上就回傳 null。 */
export function parseStage2Reply(text: string): Stage2Parsed | null {
  const match = text.match(STAGE2_PATTERN)
  if (!match) return null
  const [, numberText, reflection, question] = match
  const questionNumber = Number(numberText)
  if (!Number.isFinite(questionNumber) || questionNumber < 1 || questionNumber > 10) return null
  const trimmedReflection = reflection.trim()
  const trimmedQuestion = question.trim()
  if (!trimmedQuestion) return null
  return { questionNumber, reflection: trimmedReflection, question: trimmedQuestion }
}

/** Stage 1.5 六句自評問句的第一句是固定文字，用它判斷「這輪進入 FAST 自評」。 */
export function isFastAssessmentPrompt(text: string): boolean {
  return text.includes('我知道自己的學習興趣')
}

const REPORT_MARKER = '📋 你的學習規劃報告'

/** Stage 3 總結報告的固定開頭標題，用它判斷「這輪是最終報告」。 */
export function isFinalReport(text: string): boolean {
  return text.includes(REPORT_MARKER)
}

const SECTION_MARKERS = {
  issue: '【你想談的議題】',
  status: '【目前的狀況】',
  strengths: '【你的優勢與資源】',
  directions: '【可能的探索方向】',
  fastBlock: '📊 你的 FAST Model 學習狀態',
  advice: '【探索建議】',
  resources: '🎓 推薦臺大學習資源'
} as const

const SECTION_ORDER = Object.values(SECTION_MARKERS)

const SECTION_TITLES: Record<'issue' | 'status' | 'strengths' | 'directions' | 'resources', string> = {
  issue: '你想談的議題',
  status: '目前的狀況',
  strengths: '你的優勢與資源',
  directions: '可能的探索方向',
  resources: '推薦臺大學習資源'
}

function nextMarkersAfter(marker: string): string[] {
  const idx = SECTION_ORDER.indexOf(marker as (typeof SECTION_ORDER)[number])
  return idx >= 0 ? SECTION_ORDER.slice(idx + 1) : []
}

function extractBetween(text: string, startMarker: string, endMarkers: string[]): string | null {
  const startIdx = text.indexOf(startMarker)
  if (startIdx < 0) return null
  const from = startIdx + startMarker.length
  let endIdx = text.length
  for (const marker of endMarkers) {
    const idx = text.indexOf(marker, from)
    if (idx >= 0 && idx < endIdx) endIdx = idx
  }
  const body = text.slice(from, endIdx).trim()
  return body || null
}

function toItems(body: string): string[] | undefined {
  const lines = body
    .split('\n')
    .map(line => line.replace(/^[-•]\s*/, '').trim())
    .filter(Boolean)
  return lines.length > 1 ? lines : undefined
}

const RESOURCE_ENTRY_PATTERN =
  /\d+\.\s*【([^】]+)】\s*\n📌[^\n]*\n🔗\s*連結：([^\n]+)\n💡\s*推薦原因：([^\n]+)/g

function parseResources(body: string): RecommendedResource[] {
  const resources: RecommendedResource[] = []
  for (const match of body.matchAll(RESOURCE_ENTRY_PATTERN)) {
    const [, name, url, reason] = match
    resources.push({ name: name.trim(), type: '', url: url.trim(), reason: reason.trim() })
  }
  return resources
}

const QUADRANT_MAP: Record<string, 1 | 2 | 3 | 4> = { 第一: 1, 第二: 2, 第三: 3, 第四: 4 }

export interface Stage3Parsed {
  summary: SummarySection[]
  fast?: Pick<FastAssessment, 'directionScore' | 'resourceScore' | 'quadrant' | 'advice'>
}

/** Stage 3：依固定 marker 切出五個報告段落 + FAST 象限分數／建議文字。整段解析不出來就回傳 null。 */
export function parseStage3Report(text: string): Stage3Parsed | null {
  if (!isFinalReport(text)) return null

  const summary: SummarySection[] = []
  for (const key of ['issue', 'status', 'strengths', 'directions'] as const) {
    const marker = SECTION_MARKERS[key]
    const body = extractBetween(text, marker, nextMarkersAfter(marker))
    if (!body) continue
    const items = toItems(body)
    summary.push({ key, title: SECTION_TITLES[key], body, ...(items ? { items } : {}) })
  }

  const resourceBody = extractBetween(text, SECTION_MARKERS.resources, [])
  if (resourceBody) {
    const resources = parseResources(resourceBody)
    summary.push({
      key: 'resources',
      title: SECTION_TITLES.resources,
      body: resourceBody,
      ...(resources.length ? { resources } : {})
    })
  }

  if (summary.length === 0) {
    // 一個段落都切不出來，回傳原始全文當單一段落，至少畫面不會開天窗
    return { summary: [{ key: 'raw', title: '總結報告', body: text }] }
  }

  let fast: Stage3Parsed['fast']
  const fastBody = extractBetween(text, SECTION_MARKERS.fastBlock, nextMarkersAfter(SECTION_MARKERS.fastBlock))
  const adviceBody = extractBetween(text, SECTION_MARKERS.advice, nextMarkersAfter(SECTION_MARKERS.advice))
  if (fastBody) {
    const directionMatch = fastBody.match(/學習方向明確度[：:]\s*([\d.]+)/)
    const resourceMatch = fastBody.match(/學習資源掌握度[：:]\s*([\d.]+)/)
    const quadrantMatch = fastBody.match(/你的落點[：:]\s*(第[一二三四])象限/)
    if (directionMatch && resourceMatch && quadrantMatch) {
      fast = {
        directionScore: Number(directionMatch[1]),
        resourceScore: Number(resourceMatch[1]),
        quadrant: QUADRANT_MAP[quadrantMatch[1]],
        advice: adviceBody ?? undefined
      }
    }
  }

  return { summary, fast }
}

/**
 * AI 的總結報告裡沒有專門對應自我察覺卡 coreInsight/nextExplorationDirection/keywords 的欄位，
 * 只能從已解析出的段落做啟發式擷取——這是有損的簡化，先這樣做，效果不夠好再考慮讓後端 prompt
 * 額外吐一段機器可讀欄位（見 handoff 規劃文件「待確認事項」）。
 */
export function buildSelfAwarenessCard(
  topicLabel: string,
  summary: SummarySection[]
): { coreInsight: string; nextExplorationDirection: string; resources: RecommendedResource[] } {
  const issue = summary.find(s => s.key === 'issue')
  const directions = summary.find(s => s.key === 'directions')
  const resourcesSection = summary.find(s => s.key === 'resources')

  const firstSentence = (text: string | undefined): string => {
    if (!text) return topicLabel
    const first = text.split(/(?<=[。！？])/).find(Boolean)
    return (first ?? text).trim()
  }

  return {
    coreInsight: firstSentence(issue?.body),
    nextExplorationDirection: directions?.items?.[0] ?? firstSentence(directions?.body),
    resources: resourcesSection?.resources ?? []
  }
}

import { ref, type Ref } from 'vue'
import { useI18n } from 'vue-i18n'
import type { ConversationTurn, Exploration } from '@/types'
import { sendAdvisingMessage } from '@/services/advisingApi'
import { updateExploration } from '@/storage/explorations'
import {
  buildSelfAwarenessCard,
  isFinalReport,
  isFastAssessmentPrompt,
  parseStage2Reply,
  parseStage3Report
} from '@/services/advisingParser'
import { TOPICS } from '@/data/topics'

export interface SendOutcome {
  reply: string
  isFinal: boolean
}

/**
 * 驅動與 AdvisingChatService 的真實多輪對話：送出使用者這輪的回覆、串流累積 AI 回覆、
 * 依目前階段解析回覆內容並寫回 exploration（含 localStorage 持久化，讓重新整理頁面後
 * 能靠 exploration.history 接續對話——後端沒有 session，一定要整包歷史紀錄重送）。
 */
export function useAdvisingConversation(exploration: Ref<Exploration | null>) {
  const { t } = useI18n()
  const sending = ref(false)
  const streamingText = ref('')
  const error = ref<string | null>(null)

  function topicLabelOf(current: Exploration): string {
    return current.topicCustomLabel ?? t(TOPICS.find(o => o.key === current.topic)?.labelKey ?? current.topic)
  }

  function historyOf(): ConversationTurn[] {
    return exploration.value?.history ?? []
  }

  /** 送出一輪使用者訊息，回傳這輪 AI 的完整回覆（已經套用過 Stage 2/3 解析並寫回 exploration）。 */
  async function send(userText: string): Promise<SendOutcome> {
    const current = exploration.value
    if (!current) throw new Error('exploration not loaded')

    sending.value = true
    streamingText.value = ''
    error.value = null

    try {
      const history = historyOf()
      const reply = await sendAdvisingMessage(userText, history, delta => {
        streamingText.value += delta
      })

      const nextHistory: ConversationTurn[] = [
        ...history,
        { role: 'user', text: userText },
        { role: 'model', text: reply }
      ]
      const patch: Partial<Exploration> = { history: nextHistory }
      let isFinal = false

      const stage2 = parseStage2Reply(reply)
      if (stage2) {
        const answers = [...current.answers]
        const idx = answers.findIndex(a => a.questionIndex === stage2.questionNumber - 1)
        const entry = {
          questionIndex: stage2.questionNumber - 1,
          text: answers[idx]?.text ?? '',
          updatedAt: new Date().toISOString(),
          reflection: stage2.reflection,
          question: stage2.question,
          rawReply: reply,
          historyLength: nextHistory.length
        }
        if (idx >= 0) answers[idx] = { ...answers[idx], ...entry }
        else answers.push(entry)
        patch.answers = answers
      } else if (isFinalReport(reply)) {
        isFinal = true
        const parsed = parseStage3Report(reply)
        const summary = parsed?.summary ?? [{ key: 'raw' as const, title: '總結報告', body: reply }]
        patch.summary = summary
        if (parsed?.fast && current.fast) {
          patch.fast = { ...current.fast, ...parsed.fast }
        }
        const topicLabel = topicLabelOf(current)
        patch.card = {
          topicLabel,
          date: new Date().toISOString().slice(0, 10),
          ...buildSelfAwarenessCard(topicLabel, summary)
        }
        patch.status = 'completed'
      } else if (!isFastAssessmentPrompt(reply) && current.answers.length > 0) {
        // 非預期格式（不是新一題、不是總結報告、也不是 FAST 自評提示）——多半是 Stage 2
        // 期間解析失敗，用原始文字頂著一個新題目卡位，至少不讓畫面開天窗。
        const answers = [...current.answers]
        answers.push({
          questionIndex: answers.length,
          text: '',
          updatedAt: new Date().toISOString(),
          rawReply: reply,
          historyLength: nextHistory.length
        })
        patch.answers = answers
      }

      exploration.value = updateExploration(current.id, patch)
      return { reply, isFinal }
    } catch (err) {
      error.value = err instanceof Error ? err.message : String(err)
      // 錯誤原因（後端回的 error 訊息、或 fetch/串流讀取本身的例外）留一份在 console，
      // 不然畫面只會顯示制式的「傳送失敗」，事後完全查不出當下實際發生什麼事。
      console.error('[useAdvisingConversation] send failed', err)
      throw err
    } finally {
      sending.value = false
    }
  }

  /**
   * 送出 Stage 1.5 的六題自評分數（後端期待的格式是 "4,5,3,2,4,3"）。
   * 分數本身先存起來；directionScore/resourceScore/quadrant/advice 等 Stage 3 報告解析出來才補上。
   */
  async function submitFastScores(scores: number[]): Promise<SendOutcome> {
    const current = exploration.value
    if (!current) throw new Error('exploration not loaded')
    exploration.value = updateExploration(current.id, { fast: { scores } })
    return send(scores.join(','))
  }

  return { sending, streamingText, error, send, submitFastScores }
}

import * as forge from 'node-forge'
import { readAuthToken, readModelPreference } from './auth'
import type { ConversationTurn } from '@/types'

/** 對應 chatai_backend RunController 的 AdvisingFlowIndex（學習規劃探索助手） */
const FLOW_ID = '7'

interface SseStreamPayload {
  delta?: string
  source?: string
  done?: boolean
  error?: string
}

/**
 * RSA-OAEP/SHA-256 加密簽名，原樣對應 _frontend/chatai/src/hooks/useAICall.ts 的 encryptSignature()。
 * 後端（ValidateSignatureFilter）解密後從內容裡取出 fingerprint/timestamp/apiFlow 決定要不要放行、
 * 走哪個 flow 分支，所以這段邏輯不能簡化，兩邊必須一致。
 */
async function encryptSignature(publicKeyBase64: string, text: string): Promise<string> {
  const publicKeyPem = `-----BEGIN PUBLIC KEY-----\n${publicKeyBase64}\n-----END PUBLIC KEY-----`
  const publicKey = forge.pki.publicKeyFromPem(publicKeyPem)
  const encryptedBytes = publicKey.encrypt(text, 'RSA-OAEP', { md: forge.md.sha256.create() })
  return forge.util.encode64(encryptedBytes)
}

/**
 * 簽名的 fingerprint 只被伺服器拿來驗證格式與時間戳新鮮度（10 分鐘內），不比對特定裝置身分，
 * 所以這裡用一個持久化在本機的隨機字串就足夠，不需要引入 fingerprintjs。
 */
function getFingerprint(): string {
  const KEY = 'lex.fingerprint'
  try {
    const existing = localStorage.getItem(KEY)
    if (existing) return existing
    const next = crypto.randomUUID()
    localStorage.setItem(KEY, next)
    return next
  } catch {
    return crypto.randomUUID()
  }
}

/** 對應 _frontend/chatai/src/lib/utils.ts 的 getApiUrl()：組完整絕對網址，同源/跨源都能打。 */
function getApiUrl(path: string): string {
  const apiUrl = import.meta.env.VITE_API_URL as string | undefined
  const normalizedPath = path.startsWith('/') ? path : `/${path}`
  if (!apiUrl?.trim()) return normalizedPath
  return `${apiUrl.replace(/\/$/, '')}${normalizedPath}`
}

/** 把一行文字解析成 SSE payload；不是 `data: ` 開頭的行回傳 null。 */
function parseSseLine(rawLine: string): SseStreamPayload | null {
  const line = rawLine.trim()
  if (!line.startsWith('data: ')) return null
  return JSON.parse(line.slice('data: '.length))
}

export class AdvisingApiError extends Error {}

/**
 * 呼叫 flow=7 的串流 API（POST /api/api/run?stream=true——這個看似重複的路徑跟主聊天站
 * useAICall.ts 的 getApiUrl("/api/run...") 用法一致，因為後端 UsePathBase("/api") 又疊了一層
 * Controller 自己的 [Route("api/run")]），逐段把 delta 丟給 onDelta，回傳累積後的完整文字。
 */
export async function sendAdvisingMessage(
  content: string,
  history: ConversationTurn[],
  onDelta?: (delta: string, accumulated: string) => void
): Promise<string> {
  const publicKey = import.meta.env.VITE_API_PUBLICKEY as string | undefined
  if (!publicKey) throw new AdvisingApiError('缺少 VITE_API_PUBLICKEY 設定')

  const token = readAuthToken()
  if (!token) throw new AdvisingApiError('缺少登入憑證')

  const timestamp = Date.now()
  const signature = await encryptSignature(publicKey, `${getFingerprint()} ${timestamp} ${FLOW_ID}`)

  const res = await fetch(getApiUrl('/api/run?stream=true'), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: signature,
      'X-Access-Token': `Bearer ${token}`
    },
    body: JSON.stringify({ input_value: content, history, model: readModelPreference() })
  })

  if (!res.ok || !res.body) {
    const errorText = await res.text()
    throw new AdvisingApiError(errorText || `串流請求失敗 (${res.status})`)
  }

  const reader = res.body.getReader()
  const decoder = new TextDecoder('utf-8')
  let buffer = ''
  let accumulated = ''

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    buffer += decoder.decode(value, { stream: true })
    const events = buffer.split('\n\n')
    buffer = events.pop() ?? ''
    for (const raw of events) {
      const payload = parseSseLine(raw)
      if (!payload) continue
      if (payload.error) throw new AdvisingApiError(payload.error)
      if (payload.delta) {
        accumulated += payload.delta
        onDelta?.(payload.delta, accumulated)
      }
    }
  }

  return accumulated
}

