import type { Exploration, TopicKey } from '@/types'
import { STORAGE_KEYS } from './keys'

interface CreateInput {
  topic: TopicKey
  topicCustomLabel?: string
}

function readAll(): Exploration[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.explorations)
    if (!raw) return []
    return JSON.parse(raw) as Exploration[]
  } catch {
    return []
  }
}

function writeAll(list: Exploration[]): void {
  try {
    localStorage.setItem(STORAGE_KEYS.explorations, JSON.stringify(list))
  } catch {
    // localStorage unavailable (quota exceeded, private mode) — fail silently for this demo
  }
}

function generateId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return crypto.randomUUID()
  }
  return `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
}

export function listExplorations(): Exploration[] {
  const all = readAll()
  return [...all].sort((a, b) =>
    new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
  )
}

export function getExploration(id: string): Exploration | null {
  return readAll().find(r => r.id === id) ?? null
}

export function createExploration(input: CreateInput): Exploration {
  const now = new Date().toISOString()
  const record: Exploration = {
    id: generateId(),
    topic: input.topic,
    topicCustomLabel: input.topicCustomLabel,
    answers: [],
    status: 'in-progress',
    createdAt: now,
    updatedAt: now
  }
  writeAll([...readAll(), record])
  return record
}

export function updateExploration(
  id: string,
  patch: Partial<Omit<Exploration, 'id' | 'createdAt'>>
): Exploration {
  const all = readAll()
  const idx = all.findIndex(r => r.id === id)
  if (idx < 0) throw new Error(`exploration ${id} not found`)
  const updated: Exploration = {
    ...all[idx],
    ...patch,
    // 呼叫端可明確指定 updatedAt（Demo 資料需要回填較早的時間），否則一律更新為現在
    updatedAt: patch.updatedAt ?? new Date().toISOString()
  }
  all[idx] = updated
  writeAll(all)
  return updated
}

export function findInProgress(): Exploration | null {
  return listExplorations().find(r => r.status === 'in-progress') ?? null
}

export function deleteExploration(id: string): void {
  writeAll(readAll().filter(r => r.id !== id))
}

export type Locale = 'zh-TW' | 'en'
export type MotionMode = 'system' | 'full' | 'reduced'

export type TopicKey =
  | 'academics'
  | 'course-selection'
  | 'career'
  | 'time-management'
  | 'motivation'
  | 'other'

export interface Settings {
  locale: Locale
  motionMode: MotionMode
  studentName: string
  /** 打字機每字間隔（毫秒/字）；動態關閉時不生效 */
  typingSpeedMs: number
}

export interface Answer {
  questionIndex: number
  text: string
  updatedAt: string
  /**
   * 真實對話模式下，這題實際的反映／提問文字是 AI 當輪動態產生的，不是固定題庫；
   * 從 AdvisingChatService 的回覆解析失敗時兩者都留空，畫面退回顯示 rawReply。
   */
  reflection?: string
  question?: string
  /** 解析失敗時的原始 AI 回覆全文，供畫面兜底顯示，避免解析失敗時開天窗 */
  rawReply?: string
  /**
   * 這題的對話回合結束後，exploration.history 的長度。修改較早的回答時要把 history
   * 一併截回這個長度再重送，否則後端會拿到「已經被使用者捨棄」的未來回合，AI 會混亂。
   */
  historyLength?: number
}

export interface SummarySection {
  key: 'issue' | 'status' | 'strengths' | 'directions' | 'resources' | 'raw'
  title: string
  /** 純文字內容：畫面段落與匯出報告共用 */
  body: string
  /** 條列呈現時的項目（設計稿中「優勢與資源」「可能的探索方向」為條列） */
  items?: string[]
  /** 以資源卡呈現時的推薦資源 */
  resources?: RecommendedResource[]
}

/**
 * AdvisingChatService Stage 1.5 的 FAST Model 六題自評結果。
 * scores 在使用者填完六題自評當下就有了；directionScore/resourceScore/quadrant/advice
 * 要等 Stage 3 總結報告解析出來才補上，所以都是可選欄位。
 */
export interface FastAssessment {
  /** 1~6 分，依序對應六句自評問句 */
  scores: number[]
  directionScore?: number
  resourceScore?: number
  quadrant?: 1 | 2 | 3 | 4
  /** Stage 3 報告裡對應象限的一段固定探索建議文字 */
  advice?: string
}

/** 對應 chatai_backend RunController body.history 的單輪對話紀錄 */
export interface ConversationTurn {
  role: 'user' | 'model'
  text: string
}

export interface RecommendedResource {
  name: string
  type: string
  url: string
  reason: string
  /** 自我察覺卡頁尾使用的簡稱；未提供時退回 name */
  shortName?: string
}

export interface SelfAwarenessCard {
  topicLabel: string
  date: string
  coreInsight: string
  nextExplorationDirection: string
  /** 卡面上的關鍵字標籤（設計稿為 3 個 # 標籤） */
  keywords?: string[]
  resources: RecommendedResource[]
}

export type ExplorationStatus = 'in-progress' | 'completed'

export interface Exploration {
  id: string
  topic: TopicKey
  topicCustomLabel?: string
  answers: Answer[]
  summary?: SummarySection[]
  card?: SelfAwarenessCard
  status: ExplorationStatus
  createdAt: string
  updatedAt: string
  /**
   * 真實對話模式下的完整多輪對話紀錄，每次呼叫 API 都要整包帶入（後端沒有 session）。
   * 沒有這份資料就無法在重新整理頁面後接續對話，所以要跟其他欄位一起存進 localStorage。
   */
  history?: ConversationTurn[]
  fast?: FastAssessment
}

