1	import * as forge from "node-forge";
2	import { type Ref } from "vue";
3	import { MessageStatus as Status } from "@/lib/type";
4	import { Role } from "@/lib/enum";
5	import { getApiUrl } from "@/lib/utils";
6	import type { Message } from "@/lib/type";
7	
8	export type CallConfig = {
9	  content: string;
10	  flowId: string;
11	  loadingText?: string;
12	  history?: { role: "user" | "model"; text: string }[];
13	  image?: { mimeType: string; data: string };
14	  /** flow=7（學習規劃探索助手）用：切換底層呼叫的 AI 供應商，例如 "gemini"（預設）、"openai"、"claude" */
15	  model?: string;
16	};
17	
18	export class QuotaExceededError extends Error {
19	  constructor(message: string) {
20	    super(message);
21	    this.name = "QuotaExceededError";
22	  }
23	}
24	
25	export interface AICallContext {
26	  messages: Ref<Message[][]>;
27	  publicKey: string;
28	  fingerprint: Ref<string> | undefined;
29	  jwtToken: Ref<string>;
30	  route: { query: { flow?: string | string[] } };
31	}
32	
33	/**
34	 * 加密簽名
35	 */
36	export async function encryptSignature(
37	  publicKeyBase64: string,
38	  text: string,
39	): Promise<string> {
40	  const publicKeyPem = `-----BEGIN PUBLIC KEY-----\n${publicKeyBase64}\n-----END PUBLIC KEY-----`;
41	  const publicKey = forge.pki.publicKeyFromPem(publicKeyPem);
42	
43	  const encryptedBytes = publicKey.encrypt(text, "RSA-OAEP", {
44	    md: forge.md.sha256.create(),
45	  });
46	
47	  return forge.util.encode64(encryptedBytes);
48	}
49	
50	/**
51	 * 顯示錯誤訊息
52	 */
53	function showErrorMessage(
54	  messages: Ref<Message[][]>,
55	  mIdx: number,
56	  idx: number,
57	) {
58	  messages.value[mIdx][idx] = {
59	    role: Role.Assistant,
60	    content: `beta 測試版發生錯誤，懇請重新登入或撥冗使用 QR code 進行回報`,
61	    timestamp: Date.now(),
62	    status: Status.Error,
63	  };
64	}
65	
66	/**
67	 * 執行 AI 調用（包含簽名生成）
68	 */
69	async function executeAICall(
70	  context: AICallContext,
71	  mIdx: number,
72	  idx: number,
73	  config: CallConfig,
74	): Promise<void> {
75	  const timestamp = Date.now();
76	  const signature = await encryptSignature(
77	    context.publicKey,
78	    `${context.fingerprint?.value} ${timestamp} ${config.flowId}`,
79	  );
80	
81	  // flowId=6（Gemini File Search RAG）、flowId=7（學習規劃探索助手）、
82	  // flowId=8（未來教室設備支援助理）、flowId=9（學習規劃探索助手舊版聊天 UI，跟 7 共用後端）
83	  // 走串流，其他 flow 維持非串流
84	  if (
85	    config.flowId === "6" ||
86	    config.flowId === "7" ||
87	    config.flowId === "8" ||
88	    config.flowId === "9"
89	  ) {
90	    await callStream(context, mIdx, idx, config, signature);
91	  } else {
92	    await callNonStream(context, mIdx, idx, config, signature);
93	  }
94	}
95	
96	/**
97	 * 非流式 AI 調用
98	 */
99	async function callNonStream(
100	  context: AICallContext,
101	  mIdx: number,
102	  idx: number,
103	  config: CallConfig,
104	  signature: string,
105	) {
106	  context.messages.value[mIdx][idx] = {
107	    role: Role.Assistant,
108	    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
109	    timestamp: Date.now(),
110	    status: Status.Pending,
111	  };
112	
113	  const res = await fetch(getApiUrl("/api/run?stream=false"), {
114	    method: "POST",
115	    headers: {
116	      "Content-Type": "application/json",
117	      Authorization: signature,
118	      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
119	    },
120	    body: JSON.stringify({ input_value: config.content }),
121	  });
122	
123	  if (!res.ok) {
124	    const errorText = await res.text();
125	    // 檢查是否是額度用光的錯誤
126	    if (
127	      res.status === 429 ||
128	      errorText.includes("quota") ||
129	      errorText.includes("額度") ||
130	      errorText.includes("limit") ||
131	      errorText.includes("exceeded")
132	    ) {
133	      throw new QuotaExceededError(errorText);
134	    }
135	    throw new Error(errorText);
136	  }
137	
138	  const data = await res.json();
139	
140	  if (data.detail) {
141	    // 檢查 detail 中是否包含額度相關錯誤
142	    const detailStr = String(data.detail);
143	    if (
144	      detailStr.includes("quota") ||
145	      detailStr.includes("額度") ||
146	      detailStr.includes("limit") ||
147	      detailStr.includes("exceeded")
148	    ) {
149	      throw new QuotaExceededError(detailStr);
150	    }
151	    throw new Error(detailStr);
152	  }
153	
154	  data.outputs?.[0].outputs.forEach((output: any, i: number) => {
155	    context.messages.value[mIdx][idx + i] = {
156	      role: Role.Assistant,
157	      content: output.artifacts.message,
158	      timestamp: Date.now(),
159	      status: Status.End,
160	      source: config.flowId === "5"
161	        ? output.results.message.data.properties.source.source
162	        : "",
163	    };
164	  });
165	}
166	
167	type SseStreamPayload = {
168	  delta?: string;
169	  source?: string;
170	  done?: boolean;
171	  error?: string;
172	};
173	
174	function isQuotaErrorText(status: number, text: string): boolean {
175	  return (
176	    status === 429 ||
177	    text.includes("quota") ||
178	    text.includes("額度") ||
179	    text.includes("limit") ||
180	    text.includes("exceeded")
181	  );
182	}
183	
184	/** 把一行文字解析成 SSE payload；不是 `data: ` 開頭的行（例如空白分隔行）回傳 null */
185	function parseSseLine(rawLine: string): SseStreamPayload | null {
186	  const line = rawLine.trim();
187	  if (!line.startsWith("data: ")) return null;
188	  return JSON.parse(line.slice("data: ".length));
189	}
190	
191	/** 讀取一個 SSE response body，逐段解析出 payload 陣列（可能因為 chunk 邊界而一次拿到多個或零個） */
192	async function readSseChunk(
193	  reader: ReadableStreamDefaultReader<Uint8Array>,
194	  decoder: TextDecoder,
195	  bufferRef: { value: string },
196	): Promise<{ done: boolean; payloads: SseStreamPayload[] }> {
197	  const { done, value } = await reader.read();
198	  if (done) return { done: true, payloads: [] };
199	
200	  bufferRef.value += decoder.decode(value, { stream: true });
201	  const events = bufferRef.value.split("\n\n");
202	  bufferRef.value = events.pop() ?? ""; // 最後一段可能還不完整，留到下一輪繼續接
203	
204	  const payloads = events
205	    .map(parseSseLine)
206	    .filter((p): p is SseStreamPayload => p !== null);
207	  return { done: false, payloads };
208	}
209	
210	type StreamAccumulator = {
211	  content: string;
212	  source: string;
213	  hasReceivedContent: boolean;
214	};
215	
216	/** 套用單一 SSE payload 到累積狀態，並即時更新畫面上的訊息內容 */
217	function applyStreamPayload(
218	  payload: SseStreamPayload,
219	  acc: StreamAccumulator,
220	  context: AICallContext,
221	  mIdx: number,
222	  idx: number,
223	) {
224	  if (payload.error) throw new Error(payload.error);
225	
226	  if (payload.delta) {
227	    acc.content += payload.delta;
228	    acc.hasReceivedContent = true;
229	    context.messages.value[mIdx][idx] = {
230	      role: Role.Assistant,
231	      content: acc.content,
232	      timestamp: Date.now(),
233	      status: Status.Receiving,
234	    };
235	  }
236	
237	  if (payload.done) acc.source = payload.source ?? "";
238	}
239	
240	/** 讀完整個 SSE response body，過程中即時更新畫面，回傳最終累積狀態 */
241	async function consumeSseStream(
242	  res: Response,
243	  context: AICallContext,
244	  mIdx: number,
245	  idx: number,
246	): Promise<StreamAccumulator> {
247	  const reader = res.body!.getReader();
248	  const decoder = new TextDecoder("utf-8");
249	  const bufferRef = { value: "" };
250	  const acc: StreamAccumulator = { content: "", source: "", hasReceivedContent: false };
251	
252	  while (true) {
253	    const { done, payloads } = await readSseChunk(reader, decoder, bufferRef);
254	    if (done) break;
255	    for (const payload of payloads) {
256	      applyStreamPayload(payload, acc, context, mIdx, idx);
257	    }
258	  }
259	
260	  return acc;
261	}
262	
263	/**
264	 * 串流 AI 調用（flowId=6：Gemini File Search RAG；flowId=7／9：學習規劃探索助手；
265	 * flowId=8：未來教室設備支援助理）
266	 * 後端以 SSE 逐段吐出文字，格式為 `data: {delta, source, done, error}\n\n`
267	 */
268	async function callStream(
269	  context: AICallContext,
270	  mIdx: number,
271	  idx: number,
272	  config: CallConfig,
273	  signature: string,
274	) {
275	  context.messages.value[mIdx][idx] = {
276	    role: Role.Assistant,
277	    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
278	    timestamp: Date.now(),
279	    status: Status.Pending,
280	  };
281	
282	  const res = await fetch(getApiUrl("/api/run?stream=true"), {
283	    method: "POST",
284	    headers: {
285	      "Content-Type": "application/json",
286	      Authorization: signature,
287	      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
288	    },
289	    body: JSON.stringify({
290	      input_value: config.content,
291	      ...(config.history ? { history: config.history } : {}),
292	      ...(config.image ? { image: config.image } : {}),
293	      ...(config.model ? { model: config.model } : {}),
294	    }),
295	  });
296	
297	  if (!res.ok || !res.body) {
298	    const errorText = await res.text();
299	    if (isQuotaErrorText(res.status, errorText)) {
