// ==================== AI 調用 ====================

/**
 * flowId=7／9（學習規劃探索助手）、flowId=8（未來教室設備支援助理）共用：
 * 把目前這一輪之前的完整對話紀錄轉成 Gemini 的 user/model 格式，讓後端組成多輪 contents 陣列，
 * 模型才能依對話紀錄自行判斷目前進度、延續前面討論的內容。
 */
function buildChatHistory(): { role: "user" | "model"; text: string }[] {
  return messages.value.slice(0, -1).flatMap((pair) =>
    pair
      .filter(
        (m) =>
          (m.role === Role.User || m.role === Role.Assistant) &&
          m.status !== Status.Error,
      )
      .map((m) => ({
        role: m.role === Role.User ? ("user" as const) : ("model" as const),
        text: m.content,
      })),
  );
}

const HISTORY_FLOW_IDS = new Set(["7", "8", "9"]);

/**
 * 呼叫 AI，根據 flow 設定處理
 */
async function callAIWrapper(
  messageIndex: number,
  content: string,
  flowId?: string,
  loadingText?: string,
  image?: { mimeType: string; data: string },
) {
  const context: AICallContext = {
    messages,
    publicKey,
    fingerprint,
    jwtToken,
    route,
  };

  // flow=7（學習規劃探索助手）用：網址帶 ?model=openai / ?model=claude 切換供應商，預設 gemini
  const modelParam = route.query.model?.toString();

  // 1. 優先使用 route.query.flow（用於測試等場景）
  if (route.query.flow) {
    const flowIds = route.query.flow.toString().split(",");
    for (let index = 0; index < flowIds.length; index++) {
      const id = flowIds[index];
      const config: CallConfig = {
        content,
        flowId: id,
        loadingText,
        ...(HISTORY_FLOW_IDS.has(id) ? { history: buildChatHistory() } : {}),
        ...(image ? { image } : {}),
        ...(modelParam ? { model: modelParam } : {}),
      };
      await callAI(context, messageIndex, 1, config, id === "0");
    }
    return;
  }

  // 2. 使用傳入的 flowId，或默認使用 "0"
  const finalFlowId = flowId || "0";
  const config: CallConfig = {
    content,
    flowId: finalFlowId,
    loadingText,
    ...(HISTORY_FLOW_IDS.has(finalFlowId)
      ? { history: buildChatHistory() }
      : {}),
    ...(image ? { image } : {}),
    ...(modelParam ? { model: modelParam } : {}),
  };

