import * as forge from "node-forge";
import { type Ref } from "vue";
import { MessageStatus as Status } from "@/lib/type";
import { Role } from "@/lib/enum";
import { getApiUrl } from "@/lib/utils";
import type { Message } from "@/lib/type";

export type CallConfig = {
  content: string;
  flowId: string;
  loadingText?: string;
  history?: { role: "user" | "model"; text: string }[];
  image?: { mimeType: string; data: string };
  /** flow=7（學習規劃探索助手）用：切換底層呼叫的 AI 供應商，例如 "gemini"（預設）、"openai"、"claude" */
  model?: string;
};

export class QuotaExceededError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "QuotaExceededError";
  }
}

/**
 * 判斷是不是「AI 服務暫時不可用」類型的錯誤：額度用光、429 限流，或模型過載
 * （Gemini 503 UNAVAILABLE／"high demand"、overloaded 等）。這類錯誤不是我們程式的 bug，
 * 過一下重試通常就會好，跟其他真正非預期的例外要分開顯示不同訊息，不要每次都用暗示系統
 * 故障的「beta 測試版發生錯誤」字樣，使用者也比較知道該重試還是該回報問題。
 */
const TRANSIENT_AI_ERROR_PATTERN =
  /429|503|quota|額度|limit|exceeded|overloaded|unavailable|high demand/i;

function isTransientAiError(err: unknown): boolean {
  return err instanceof Error && TRANSIENT_AI_ERROR_PATTERN.test(err.message);
}

export interface AICallContext {
  messages: Ref<Message[][]>;
  publicKey: string;
  fingerprint: Ref<string> | undefined;
  jwtToken: Ref<string>;
  route: { query: { flow?: string | string[] } };
}

/**
 * 加密簽名
 */
export async function encryptSignature(
  publicKeyBase64: string,
  text: string,
): Promise<string> {
  const publicKeyPem = `-----BEGIN PUBLIC KEY-----\n${publicKeyBase64}\n-----END PUBLIC KEY-----`;
  const publicKey = forge.pki.publicKeyFromPem(publicKeyPem);

  const encryptedBytes = publicKey.encrypt(text, "RSA-OAEP", {
    md: forge.md.sha256.create(),
  });

  return forge.util.encode64(encryptedBytes);
}

/**
 * 顯示錯誤訊息
 */
function showErrorMessage(
  messages: Ref<Message[][]>,
  mIdx: number,
  idx: number,
  error?: unknown,
) {
  const content = isTransientAiError(error)
    ? "AI 服務目前忙碌（可能是額度限制或模型過載），請稍後再試一次。"
    : `beta 測試版發生錯誤，懇請重新登入或撥冗使用 QR code 進行回報`;
  messages.value[mIdx][idx] = {
    role: Role.Assistant,
    content,
    timestamp: Date.now(),
    status: Status.Error,
  };
}

/**
 * 執行 AI 調用（包含簽名生成）
 */
async function executeAICall(
  context: AICallContext,
  mIdx: number,
  idx: number,
  config: CallConfig,
): Promise<void> {
  const timestamp = Date.now();
  const signature = await encryptSignature(
    context.publicKey,
    `${context.fingerprint?.value} ${timestamp} ${config.flowId}`,
  );

  // flowId=6（Gemini File Search RAG）、flowId=7（學習規劃探索助手）、
  // flowId=8（未來教室設備支援助理）、flowId=9（學習規劃探索助手舊版聊天 UI，跟 7 共用後端）
  // 走串流，其他 flow 維持非串流
  if (
    config.flowId === "6" ||
    config.flowId === "7" ||
    config.flowId === "8" ||
    config.flowId === "9"
  ) {
    await callStream(context, mIdx, idx, config, signature);
  } else {
    await callNonStream(context, mIdx, idx, config, signature);
  }
}

/**
 * 非流式 AI 調用
 */
async function callNonStream(
  context: AICallContext,
  mIdx: number,
  idx: number,
  config: CallConfig,
  signature: string,
) {
  context.messages.value[mIdx][idx] = {
    role: Role.Assistant,
    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
    timestamp: Date.now(),
    status: Status.Pending,
  };

  const res = await fetch(getApiUrl("/api/run?stream=false"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: signature,
      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
    },
    body: JSON.stringify({ input_value: config.content }),
  });

  if (!res.ok) {
    const errorText = await res.text();
    if (isQuotaErrorText(res.status, errorText)) {
      throw new QuotaExceededError(errorText);
    }
    throw new Error(errorText);
  }

  const data = await res.json();

  if (data.detail) {
    // 檢查 detail 中是否包含額度相關錯誤
    const detailStr = String(data.detail);
    if (
      detailStr.includes("quota") ||
      detailStr.includes("額度") ||
      detailStr.includes("limit") ||
      detailStr.includes("exceeded")
    ) {
      throw new QuotaExceededError(detailStr);
    }
    throw new Error(detailStr);
  }

  data.outputs?.[0].outputs.forEach((output: any, i: number) => {
    context.messages.value[mIdx][idx + i] = {
      role: Role.Assistant,
      content: output.artifacts.message,
      timestamp: Date.now(),
      status: Status.End,
      source: config.flowId === "5"
        ? output.results.message.data.properties.source.source
        : "",
    };
  });
}

type SseStreamPayload = {
  delta?: string;
  source?: string;
  done?: boolean;
  error?: string;
};

function isQuotaErrorText(status: number, text: string): boolean {
  return (
    status === 429 ||
    text.includes("quota") ||
    text.includes("額度") ||
    text.includes("limit") ||
    text.includes("exceeded")
  );
}

/** 把一行文字解析成 SSE payload；不是 `data: ` 開頭的行（例如空白分隔行）回傳 null */
function parseSseLine(rawLine: string): SseStreamPayload | null {
  const line = rawLine.trim();
  if (!line.startsWith("data: ")) return null;
  return JSON.parse(line.slice("data: ".length));
}

/** 讀取一個 SSE response body，逐段解析出 payload 陣列（可能因為 chunk 邊界而一次拿到多個或零個） */
async function readSseChunk(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  decoder: TextDecoder,
  bufferRef: { value: string },
): Promise<{ done: boolean; payloads: SseStreamPayload[] }> {
  const { done, value } = await reader.read();
  if (done) return { done: true, payloads: [] };

  bufferRef.value += decoder.decode(value, { stream: true });
  const events = bufferRef.value.split("\n\n");
  bufferRef.value = events.pop() ?? ""; // 最後一段可能還不完整，留到下一輪繼續接

  const payloads = events
    .map(parseSseLine)
    .filter((p): p is SseStreamPayload => p !== null);
  return { done: false, payloads };
}

type StreamAccumulator = {
  content: string;
  source: string;
  hasReceivedContent: boolean;
};

/** 套用單一 SSE payload 到累積狀態，並即時更新畫面上的訊息內容 */
function applyStreamPayload(
  payload: SseStreamPayload,
  acc: StreamAccumulator,
  context: AICallContext,
  mIdx: number,
  idx: number,
) {
  if (payload.error) throw new Error(payload.error);

  if (payload.delta) {
    acc.content += payload.delta;
    acc.hasReceivedContent = true;
    context.messages.value[mIdx][idx] = {
      role: Role.Assistant,
      content: acc.content,
      timestamp: Date.now(),
      status: Status.Receiving,
    };
  }

  if (payload.done) acc.source = payload.source ?? "";
}

/** 讀完整個 SSE response body，過程中即時更新畫面，回傳最終累積狀態 */
async function consumeSseStream(
  res: Response,
  context: AICallContext,
  mIdx: number,
  idx: number,
): Promise<StreamAccumulator> {
  const reader = res.body!.getReader();
  const decoder = new TextDecoder("utf-8");
  const bufferRef = { value: "" };
  const acc: StreamAccumulator = { content: "", source: "", hasReceivedContent: false };

  while (true) {
    const { done, payloads } = await readSseChunk(reader, decoder, bufferRef);
    if (done) break;
    for (const payload of payloads) {
      applyStreamPayload(payload, acc, context, mIdx, idx);
    }
  }

  return acc;
}

/**
 * 串流 AI 調用（flowId=6：Gemini File Search RAG；flowId=7／9：學習規劃探索助手；
 * flowId=8：未來教室設備支援助理）
 * 後端以 SSE 逐段吐出文字，格式為 `data: {delta, source, done, error}\n\n`
 */
async function callStream(
  context: AICallContext,
  mIdx: number,
  idx: number,
  config: CallConfig,
  signature: string,
) {
  context.messages.value[mIdx][idx] = {
    role: Role.Assistant,
    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
    timestamp: Date.now(),
    status: Status.Pending,
  };

  const res = await fetch(getApiUrl("/api/run?stream=true"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: signature,
      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
    },
    body: JSON.stringify({
      input_value: config.content,
      ...(config.history ? { history: config.history } : {}),
      ...(config.image ? { image: config.image } : {}),
      ...(config.model ? { model: config.model } : {}),
    }),
  });

  if (!res.ok || !res.body) {
    const errorText = await res.text();
    if (isQuotaErrorText(res.status, errorText)) {
      throw new QuotaExceededError(errorText);
    }
    throw new Error(errorText || `串流請求失敗 (${res.status})`);
  }

  const { content, source, hasReceivedContent } = await consumeSseStream(
    res,
    context,
    mIdx,
    idx,
  );

  context.messages.value[mIdx][idx] = {
    role: Role.Assistant,
    content: hasReceivedContent
      ? content
      : "目前找不到與這個問題相關的資料，請確認文件是否已上傳完成，或換個問法再試一次。",
    timestamp: Date.now(),
    status: Status.End,
    source,
  };
}

/**
 * AI 調用主函數（包含錯誤處理和額度用光自動切換）
 */
export async function callAI(
  context: AICallContext,
  mIdx: number,
  idx: number,
  config: CallConfig,
  _stream: boolean = false,
) {
  try {
    await executeAICall(context, mIdx, idx, config);
  } catch (error) {
    // 如果是額度用光且當前是 flow 0，自動切換到 flow 1
    if (
      error instanceof QuotaExceededError &&
      config.flowId === "0" &&
      !context.route.query.flow
    ) {
      console.log("額度用光，自動切換到 flow 1");
      const fallbackConfig = { ...config, flowId: "1" };
      try {
        await executeAICall(context, mIdx, idx, fallbackConfig);
        return;
      } catch (fallbackError) {
        // flow 1 也失敗，顯示錯誤
        console.error(fallbackError);
        showErrorMessage(context.messages, mIdx, idx);
        return;
      }
    }

    // 其他錯誤
    console.error(error);
    showErrorMessage(context.messages, mIdx, idx);
  }
}

