import * as forge from 'node-forge'
import { readAuthToken, readModelPreference } from './auth'
import type { ConversationTurn } from '@/types'

/** 對應 chatai_backend RunController 的 AdvisingFlowIndex（學習規劃探索助手） */
const FLOW_ID = '7'

interface SseStreamPayload {
  delta?: string
  source?: string
  done?: boolean
  error?: string
}

/**
 * RSA-OAEP/SHA-256 加密簽名，原樣對應 _frontend/chatai/src/hooks/useAICall.ts 的 encryptSignature()。
 * 後端（ValidateSignatureFilter）解密後從內容裡取出 fingerprint/timestamp/apiFlow 決定要不要放行、
 * 走哪個 flow 分支，所以這段邏輯不能簡化，兩邊必須一致。
 */
async function encryptSignature(publicKeyBase64: string, text: string): Promise<string> {
  const publicKeyPem = `-----BEGIN PUBLIC KEY-----\n${publicKeyBase64}\n-----END PUBLIC KEY-----`
  const publicKey = forge.pki.publicKeyFromPem(publicKeyPem)
  const encryptedBytes = publicKey.encrypt(text, 'RSA-OAEP', { md: forge.md.sha256.create() })
  return forge.util.encode64(encryptedBytes)
}

/**
 * 簽名的 fingerprint 只被伺服器拿來驗證格式與時間戳新鮮度（10 分鐘內），不比對特定裝置身分，
 * 所以這裡用一個持久化在本機的隨機字串就足夠，不需要引入 fingerprintjs。
 */
function getFingerprint(): string {
  const KEY = 'lex.fingerprint'
  try {
    const existing = localStorage.getItem(KEY)
    if (existing) return existing
    const next = crypto.randomUUID()
    localStorage.setItem(KEY, next)
    return next
  } catch {
    return crypto.randomUUID()
  }
}

/** 對應 _frontend/chatai/src/lib/utils.ts 的 getApiUrl()：組完整絕對網址，同源/跨源都能打。 */
function getApiUrl(path: string): string {
  const apiUrl = import.meta.env.VITE_API_URL as string | undefined
  const normalizedPath = path.startsWith('/') ? path : `/${path}`
  if (!apiUrl?.trim()) return normalizedPath
  return `${apiUrl.replace(/\/$/, '')}${normalizedPath}`
}

/** 把一行文字解析成 SSE payload；不是 `data: ` 開頭的行回傳 null。 */
function parseSseLine(rawLine: string): SseStreamPayload | null {
  const line = rawLine.trim()
  if (!line.startsWith('data: ')) return null
  return JSON.parse(line.slice('data: '.length))
}

export class AdvisingApiError extends Error {}

/**
 * 判斷這個錯誤是不是額度/限流類型（AdvisingChatService.cs 呼叫 Gemini/OpenAI/Claude 失敗時，
 * 會把該服務回傳的原始錯誤內容整包放進 error 訊息，例如 Claude 429 rate_limit_error、
 * overloaded_error），讓畫面可以顯示比制式「傳送失敗」更明確的提示，不用每次都得開 DevTools
 * 才知道是額度問題還是單純網路問題。
 */
const QUOTA_ERROR_PATTERN = /429|rate.?limit|quota|overloaded/i

export function isQuotaError(err: unknown): boolean {
  return err instanceof AdvisingApiError && QUOTA_ERROR_PATTERN.test(err.message)
}

/**
 * 呼叫 flow=7 的串流 API（POST /api/api/run?stream=true——這個看似重複的路徑跟主聊天站
 * useAICall.ts 的 getApiUrl("/api/run...") 用法一致，因為後端 UsePathBase("/api") 又疊了一層
 * Controller 自己的 [Route("api/run")]），逐段把 delta 丟給 onDelta，回傳累積後的完整文字。
 */
export async function sendAdvisingMessage(
  content: string,
  history: ConversationTurn[],
  onDelta?: (delta: string, accumulated: string) => void
): Promise<string> {
  const publicKey = import.meta.env.VITE_API_PUBLICKEY as string | undefined
  if (!publicKey) throw new AdvisingApiError('缺少 VITE_API_PUBLICKEY 設定')

  const token = readAuthToken()
  if (!token) throw new AdvisingApiError('缺少登入憑證')

  const timestamp = Date.now()
  const signature = await encryptSignature(publicKey, `${getFingerprint()} ${timestamp} ${FLOW_ID}`)

  const res = await fetch(getApiUrl('/api/run?stream=true'), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: signature,
      'X-Access-Token': `Bearer ${token}`
    },
    body: JSON.stringify({ input_value: content, history, model: readModelPreference() })
  })

  if (!res.ok || !res.body) {
    const errorText = await res.text()
    throw new AdvisingApiError(errorText || `串流請求失敗 (${res.status})`)
  }

  const reader = res.body.getReader()
  const decoder = new TextDecoder('utf-8')
  let buffer = ''
  let accumulated = ''

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    buffer += decoder.decode(value, { stream: true })
    const events = buffer.split('\n\n')
    buffer = events.pop() ?? ''
    for (const raw of events) {
      const payload = parseSseLine(raw)
      if (!payload) continue
      if (payload.error) throw new AdvisingApiError(payload.error)
      if (payload.delta) {
        accumulated += payload.delta
        onDelta?.(payload.delta, accumulated)
      }
    }
  }

  return accumulated
}

